  var Q = { "fool": { "l": "\u0427\u0443\u0432\u0441\u0442\u0432\u043E \u0436\u0438\u0432\u043E\u0435, \u043D\u043E \u0431\u0435\u0437 \u043E\u0431\u0435\u0449\u0430\u043D\u0438\u0439. \u0414\u0430\u043B\u044C\u043D\u0438\u0435 \u043F\u043B\u0430\u043D\u044B \u0441 \u0432\u0430\u043C\u0438 \u0441\u0435\u0439\u0447\u0430\u0441 \u043D\u0435 \u0441\u0442\u0440\u043E\u044F\u0442.", "w": "\u041D\u043E\u0432\u0430\u044F \u0440\u043E\u043B\u044C \u043D\u0430\u0447\u043D\u0451\u0442\u0441\u044F, \u0442\u043E\u043B\u044C\u043A\u043E \u0435\u0441\u043B\u0438 \u0448\u0430\u0433\u043D\u0443\u0442\u044C \u0431\u0435\u0437 \u0433\u0430\u0440\u0430\u043D\u0442\u0438\u0439. \u0421\u0430\u043C\u0430 \u043E\u043D\u0430 \u043D\u0435 \u043F\u043E\u0434\u043F\u0438\u0448\u0435\u0442\u0441\u044F.", "m": "\u041C\u0430\u043B\u0435\u043D\u044C\u043A\u0438\u0439 \u0440\u0438\u0441\u043A \u0443\u043C\u0435\u0441\u0442\u0435\u043D. \u0412\u0441\u0451, \u0447\u0442\u043E \u0435\u0441\u0442\u044C, \u043D\u0430 \u043A\u043E\u043D \u0441\u0442\u0430\u0432\u0438\u0442\u044C \u043D\u0435 \u043D\u0430\u0434\u043E.", "a": "\u0421\u0434\u0435\u043B\u0430\u0439\u0442\u0435 \u0441\u0435\u0433\u043E\u0434\u043D\u044F \u043E\u0434\u0438\u043D \u043C\u0430\u043B\u0435\u043D\u044C\u043A\u0438\u0439 \u0448\u0430\u0433. \u041D\u0430\u0441\u0442\u043E\u044F\u0449\u0438\u0439, \u043D\u0435 \u0434\u043B\u044F \u0432\u0438\u0434\u0430." }, "mag": { "l": "\u042D\u0442\u043E\u0442 \u0447\u0435\u043B\u043E\u0432\u0435\u043A \u0441\u0430\u043C \u043D\u0430\u0439\u0434\u0451\u0442 \u0441\u043B\u043E\u0432\u0430. \u0412\u0430\u0448\u0435 \u043E\u0431\u0430\u044F\u043D\u0438\u0435 \u0442\u0443\u0442 \u043D\u0438 \u043F\u0440\u0438 \u0447\u0451\u043C.", "w": "\u041D\u0430 \u0440\u0430\u0431\u043E\u0442\u0435 \u0441\u0434\u0432\u0438\u043D\u0435\u0442 \u0434\u0435\u043B\u043E \u0442\u043E\u0442, \u0443 \u043A\u043E\u0433\u043E \u0443\u0436\u0435 \u0435\u0441\u0442\u044C \u0447\u0435\u043C \u0434\u0435\u0439\u0441\u0442\u0432\u043E\u0432\u0430\u0442\u044C. \u0421\u043E\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u0432\u043E\u0451 \u0438 \u0441\u0434\u0435\u043B\u0430\u0439\u0442\u0435 \u043E\u0434\u0438\u043D \u0448\u0430\u0433.", "m": "\u041F\u043E\u043F\u0440\u043E\u0441\u0438\u0442\u0435, \u043D\u0430\u0437\u043E\u0432\u0438\u0442\u0435 \u0446\u0435\u043D\u0443, \u0434\u043E\u0433\u043E\u0432\u043E\u0440\u0438\u0442\u0435\u0441\u044C. \u0414\u0435\u043D\u044C\u0433\u0438 \u0441\u0435\u0439\u0447\u0430\u0441 \u0438\u0434\u0443\u0442 \u043A \u0442\u043E\u043C\u0443, \u043A\u0442\u043E \u0433\u043E\u0432\u043E\u0440\u0438\u0442 \u043F\u0435\u0440\u0432\u044B\u043C.", "a": "\u0421\u043E\u0431\u0435\u0440\u0438\u0442\u0435 \u0442\u043E, \u0447\u0442\u043E \u0443\u0436\u0435 \u0435\u0441\u0442\u044C, \u0438 \u0441\u0434\u0435\u043B\u0430\u0439\u0442\u0435 \u043E\u0434\u043D\u043E \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435." }, "priestess": { "l": "\u0413\u043B\u0430\u0432\u043D\u043E\u0435 \u043D\u0435 \u0441\u043A\u0430\u0437\u0430\u043D\u043E \u0432\u0441\u043B\u0443\u0445. \u0421\u043B\u0443\u0448\u0430\u0439\u0442\u0435 \u043F\u0430\u0443\u0437\u044B: \u043A\u0440\u0430\u0441\u0438\u0432\u044B\u0435 \u0441\u043B\u043E\u0432\u0430 \u043C\u043E\u0433\u0443\u0442 \u0432\u0440\u0430\u0442\u044C.", "w": "\u0412\u0430\u0436\u043D\u043E\u0435 \u043D\u0430 \u0440\u0430\u0431\u043E\u0442\u0435 \u0435\u0449\u0451 \u0441\u043A\u0440\u044B\u0442\u043E. \u041D\u0435 \u0441\u043F\u0435\u0448\u0438\u0442\u0435 \u0441 \u0432\u044B\u0432\u043E\u0434\u0430\u043C\u0438, \u0441\u043E\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u0432\u0435\u0434\u0435\u043D\u0438\u044F.", "m": "\u0421\u043E \u0441\u0434\u0435\u043B\u043A\u0430\u043C\u0438 \u043B\u0443\u0447\u0448\u0435 \u043F\u043E\u0434\u043E\u0436\u0434\u0430\u0442\u044C. \u041F\u043E\u043A\u0430 \u043D\u0435 \u044F\u0441\u043D\u043E, \u0442\u0438\u0448\u0438\u043D\u0430 \u0434\u043E\u0440\u043E\u0436\u0435 \u043F\u043E\u0434\u043F\u0438\u0441\u0438.", "a": "\u041F\u043E\u043C\u043E\u043B\u0447\u0438\u0442\u0435 \u0438 \u043F\u043E\u0441\u043B\u0443\u0448\u0430\u0439\u0442\u0435 \u0441\u0435\u0431\u044F. \u041E\u0442\u0432\u0435\u0442 \u0443\u0436\u0435 \u0432\u043D\u0443\u0442\u0440\u0438." }, "empress": { "l": "\u0417\u0434\u0435\u0441\u044C \u043D\u0443\u0436\u043D\u0430 \u0437\u0430\u0431\u043E\u0442\u0430, \u043D\u0435 \u043F\u043E\u0434\u0432\u0438\u0433. \u0421\u043C\u043E\u0442\u0440\u0438\u0442\u0435, \u043A\u0442\u043E \u0434\u0430\u0451\u0442 \u0442\u0435\u043F\u043B\u043E \u0438 \u043A\u0442\u043E \u0435\u0433\u043E \u0442\u043E\u043B\u044C\u043A\u043E \u0436\u0434\u0451\u0442.", "w": "\u0414\u0435\u043B\u043E \u0440\u0430\u0441\u0442\u0451\u0442, \u0435\u0441\u043B\u0438 \u0435\u0433\u043E \u043F\u043E\u043B\u0438\u0432\u0430\u0442\u044C. \u0422\u044F\u043D\u0438\u0442\u0435 \u0433\u043B\u0430\u0432\u043D\u043E\u0435, \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u043E\u0435 \u043F\u043E\u0434\u043E\u0436\u0434\u0451\u0442.", "m": "\u0414\u043E\u0441\u0442\u0430\u0442\u043E\u043A \u043F\u0440\u0438\u0445\u043E\u0434\u0438\u0442 \u0447\u0435\u0440\u0435\u0437 \u0442\u0435\u043F\u043B\u043E \u0438 \u0449\u0435\u0434\u0440\u043E\u0441\u0442\u044C, \u043D\u0435 \u0447\u0435\u0440\u0435\u0437 \u0436\u0451\u0441\u0442\u043A\u0443\u044E \u044D\u043A\u043E\u043D\u043E\u043C\u0438\u044E.", "a": "\u041F\u043E\u0437\u0430\u0431\u043E\u0442\u044C\u0442\u0435\u0441\u044C \u043E \u0442\u043E\u043C, \u0447\u0442\u043E \u0443\u0436\u0435 \u0440\u0430\u0441\u0442\u0451\u0442." }, "emperor": { "l": "\u042D\u0442\u043E\u043C\u0443 \u0447\u0435\u043B\u043E\u0432\u0435\u043A\u0443 \u043D\u0443\u0436\u043D\u0430 \u043E\u043F\u043E\u0440\u0430 \u0438 \u044F\u0441\u043D\u044B\u0439 \u043F\u043E\u0440\u044F\u0434\u043E\u043A. \u041B\u044E\u0431\u043E\u0432\u044C \u0434\u043B\u044F \u043D\u0435\u0433\u043E \u2014 \u043D\u0430\u0434\u0451\u0436\u043D\u043E\u0441\u0442\u044C, \u0430 \u043D\u0435 \u0441\u044E\u0440\u043F\u0440\u0438\u0437.", "w": "\u041D\u0430 \u0440\u0430\u0431\u043E\u0442\u0435 \u0440\u0435\u0448\u0430\u044E\u0442 \u0441\u0440\u043E\u043A\u0438, \u0441\u0442\u0440\u0443\u043A\u0442\u0443\u0440\u0430 \u0438 \u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u0441\u0442\u044C. \u0411\u0435\u0437 \u043F\u043E\u0440\u044F\u0434\u043A\u0430 \u0434\u0435\u043B\u043E \u0448\u0430\u0442\u0430\u0435\u0442\u0441\u044F.", "m": "\u0411\u044E\u0434\u0436\u0435\u0442 \u0438 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u044C \u0441\u0435\u0439\u0447\u0430\u0441 \u0434\u0430\u0434\u0443\u0442 \u0431\u043E\u043B\u044C\u0448\u0435 \u043F\u043E\u043A\u043E\u044F, \u0447\u0435\u043C \u0443\u0434\u0430\u0447\u0430.", "a": "\u041D\u0430\u0432\u0435\u0434\u0438\u0442\u0435 \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u0432 \u043E\u0434\u043D\u043E\u043C \u0434\u0435\u043B\u0435. \u0414\u0435\u043D\u044C \u0432\u044B\u0440\u043E\u0432\u043D\u044F\u0435\u0442\u0441\u044F." }, "hierophant": { "l": "\u0420\u0435\u0447\u044C \u043E \u0441\u0435\u0440\u044C\u0451\u0437\u043D\u043E\u043C: \u043E \u0431\u0443\u0434\u0443\u0449\u0435\u043C \u0438 \u043E \u0442\u043E\u043C, \u043A\u0430\u043A \u043F\u0440\u0438\u043D\u044F\u0442\u043E. \u0412 \u043B\u0451\u0433\u043A\u0443\u044E \u0438\u0433\u0440\u0443 \u044D\u0442\u043E\u0442 \u0447\u0435\u043B\u043E\u0432\u0435\u043A \u043D\u0435 \u0438\u0433\u0440\u0430\u0435\u0442.", "w": "\u0421\u043F\u0440\u043E\u0441\u0438\u0442\u0435 \u0442\u043E\u0433\u043E, \u043A\u0442\u043E \u0442\u0430\u043A \u0443\u0436\u0435 \u0434\u0435\u043B\u0430\u043B. \u041F\u0440\u043E\u0432\u0435\u0440\u0435\u043D\u043D\u044B\u0439 \u043F\u0443\u0442\u044C \u0441\u0435\u0439\u0447\u0430\u0441 \u0441\u0438\u043B\u044C\u043D\u0435\u0435 \u043D\u043E\u0432\u043E\u0439 \u0438\u0434\u0435\u0438.", "m": "\u041D\u0430\u0434\u0451\u0436\u043D\u043E\u0435 \u043B\u0443\u0447\u0448\u0435 \u043C\u043E\u0434\u043D\u043E\u0433\u043E. \u041D\u043E\u0432\u043E\u0435 \u0440\u0430\u0434\u0438 \u043D\u043E\u0432\u0438\u0437\u043D\u044B \u0434\u0435\u043D\u044C\u0433\u0438 \u043D\u0435 \u0431\u0435\u0440\u0435\u0433\u0443\u0442.", "a": "\u0421\u043F\u0440\u043E\u0441\u0438\u0442\u0435 \u0441\u043E\u0432\u0435\u0442\u0430 \u0443 \u0442\u043E\u0433\u043E, \u043A\u0442\u043E \u0441\u0442\u0430\u0440\u0448\u0435 \u0432 \u044D\u0442\u043E\u043C \u0434\u0435\u043B\u0435." }, "lovers": { "l": "\u0427\u0435\u043B\u043E\u0432\u0435\u043A \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442 \u0441\u0435\u0440\u0434\u0446\u0435\u043C. \u041B\u0438\u0431\u043E \u0441\u043E\u044E\u0437 \u0432\u0441\u0435\u0440\u044C\u0451\u0437, \u043B\u0438\u0431\u043E \u0443\u0436\u0435 \u0434\u0435\u0440\u0436\u0430\u0442 \u0434\u0432\u0430 \u043F\u0443\u0442\u0438 \u0441\u0440\u0430\u0437\u0443.", "w": "\u0412\u0434\u0432\u043E\u0451\u043C \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u0441\u044F \u0442\u043E, \u0447\u0442\u043E \u043F\u043E\u043E\u0434\u0438\u043D\u043E\u0447\u043A\u0435 \u043D\u0435 \u0432\u044B\u0442\u044F\u043D\u0443\u0442\u044C. \u0418\u0449\u0438\u0442\u0435 \u043F\u0430\u0440\u0442\u043D\u0451\u0440\u0430, \u043D\u0435 \u0433\u0435\u0440\u043E\u044F.", "m": "\u0415\u0441\u043B\u0438 \u0434\u0435\u043D\u044C\u0433\u0438 \u043E\u0431\u0449\u0438\u0435 \u2014 \u0440\u0435\u0448\u0430\u0439\u0442\u0435 \u0432\u0434\u0432\u043E\u0451\u043C. \u041E\u0434\u0438\u043D \u0441\u0435\u0439\u0447\u0430\u0441 \u043E\u0448\u0438\u0431\u0451\u0442\u0441\u044F.", "a": "\u0412\u044B\u0431\u0438\u0440\u0430\u0439\u0442\u0435 \u0442\u043E, \u043A \u0447\u0435\u043C\u0443 \u043B\u0435\u0436\u0438\u0442 \u0441\u0435\u0440\u0434\u0446\u0435, \u0430 \u043D\u0435 \u0442\u043E, \u0447\u0442\u043E \xAB\u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\xBB." }, "chariot": { "l": "\u0427\u0435\u043B\u043E\u0432\u0435\u043A \u0445\u043E\u0447\u0435\u0442 \u0438\u0434\u0442\u0438 \u0432\u043F\u0435\u0440\u0451\u0434 \u0438 \u0434\u0435\u0440\u0436\u0430\u0442\u044C \u0445\u043E\u0434. \u0417\u0434\u0435\u0441\u044C \u043F\u0440\u0430\u0432\u044F\u0442, \u0430 \u043D\u0435 \u0436\u0434\u0443\u0442 \u0432 \u043D\u0435\u0436\u043D\u043E\u0441\u0442\u0438.", "w": "\u0414\u0435\u0440\u0436\u0438\u0442\u0435 \u043A\u0443\u0440\u0441 \u0438 \u043D\u0435 \u043E\u0442\u0432\u043B\u0435\u043A\u0430\u0439\u0442\u0435\u0441\u044C. \u041F\u043E\u0431\u0435\u0434\u0430 \u0441\u0435\u0439\u0447\u0430\u0441 \u0437\u0430 \u0441\u043E\u0431\u0440\u0430\u043D\u043D\u043E\u0441\u0442\u044C\u044E.", "m": "\u041D\u0443\u0436\u043D\u044B \u0441\u043A\u043E\u0440\u043E\u0441\u0442\u044C \u0438 \u044F\u0441\u043D\u044B\u0439 \u0440\u0438\u0441\u043A. \u041C\u0435\u0434\u043B\u0438\u0442\u044C \u0441 \u0441\u0443\u043C\u043C\u043E\u0439 \u043D\u0435\u043B\u044C\u0437\u044F, \u0441\u043B\u0435\u043F\u043E \u0431\u0440\u043E\u0441\u0430\u0442\u044C\u0441\u044F \u2014 \u0442\u043E\u0436\u0435.", "a": "\u0414\u0435\u0439\u0441\u0442\u0432\u0443\u0439\u0442\u0435 \u0441\u0440\u0430\u0437\u0443 \u0438 \u0434\u0435\u0440\u0436\u0438\u0442\u0435 \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435." }, "strength": { "l": "\u0421\u0438\u043B\u0430 \u0443 \u044D\u0442\u043E\u0433\u043E \u0447\u0435\u043B\u043E\u0432\u0435\u043A\u0430 \u043C\u044F\u0433\u043A\u0430\u044F. \u0414\u0435\u0440\u0436\u0438\u0442 \u0442\u0435\u0440\u043F\u0435\u043D\u0438\u0435\u043C, \u043D\u0435 \u043B\u043E\u043C\u0430\u0435\u0442 \u0443\u043B\u044C\u0442\u0438\u043C\u0430\u0442\u0443\u043C\u043E\u043C.", "w": "\u0412\u044B\u0434\u0435\u0440\u0436\u043A\u0430 \u0432\u0430\u0436\u043D\u0435\u0435 \u043D\u0430\u043F\u043E\u0440\u0430. \u0421\u043F\u043E\u043A\u043E\u0439\u043D\u043E \u0434\u043E\u0432\u0435\u0434\u0438\u0442\u0435 \u0441\u0440\u043E\u043A, \u043D\u0435 \u0434\u0430\u0432\u0438\u0442\u0435 \u043D\u0430 \u043B\u044E\u0434\u0435\u0439.", "m": "\u041D\u0435 \u0442\u0440\u0430\u0442\u044C\u0442\u0435 \u0441\u0433\u043E\u0440\u044F\u0447\u0430. \u0418\u043C\u043F\u0443\u043B\u044C\u0441 \u0441\u0435\u0439\u0447\u0430\u0441 \u0434\u043E\u0440\u043E\u0436\u0435, \u0447\u0435\u043C \u043A\u0430\u0436\u0435\u0442\u0441\u044F.", "a": "\u0418\u0434\u0438\u0442\u0435 \u043C\u044F\u0433\u043A\u043E. \u0414\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u0441\u0435\u0433\u043E\u0434\u043D\u044F \u0441\u043B\u0430\u0431\u0435\u0435 \u0442\u0435\u0440\u043F\u0435\u043D\u0438\u044F." }, "hermit": { "l": "\u0427\u0435\u043B\u043E\u0432\u0435\u043A\u0443 \u043D\u0443\u0436\u043D\u0430 \u0442\u0438\u0448\u0438\u043D\u0430 \u0438 \u0434\u0438\u0441\u0442\u0430\u043D\u0446\u0438\u044F. \u042D\u0442\u043E \u0435\u0449\u0451 \u043D\u0435 \u0437\u043D\u0430\u0447\u0438\u0442, \u0447\u0442\u043E \u043F\u043E\u044F\u0432\u0438\u043B\u0441\u044F \u043A\u0442\u043E-\u0442\u043E \u0442\u0440\u0435\u0442\u0438\u0439.", "w": "\u0422\u0438\u0445\u0430\u044F \u0440\u0430\u0431\u043E\u0442\u0430 \u0431\u0435\u0437 \u0441\u0443\u0435\u0442\u044B \u0434\u0430\u0441\u0442 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442. \u0428\u0443\u043C \u0441\u0435\u0439\u0447\u0430\u0441 \u043C\u0435\u0448\u0430\u0435\u0442.", "m": "\u0412\u0440\u0435\u043C\u044F \u0441\u043A\u0440\u043E\u043C\u043D\u043E\u0441\u0442\u0438. \u041A\u0440\u0443\u043F\u043D\u044B\u0445 \u0436\u0435\u0441\u0442\u043E\u0432 \u0441 \u0434\u0435\u043D\u044C\u0433\u0430\u043C\u0438 \u043B\u0443\u0447\u0448\u0435 \u043D\u0435 \u0434\u0435\u043B\u0430\u0442\u044C.", "a": "\u041F\u043E\u0431\u0443\u0434\u044C\u0442\u0435 \u0447\u0430\u0441 \u043D\u0430\u0435\u0434\u0438\u043D\u0435 \u0441 \u0432\u043E\u043F\u0440\u043E\u0441\u043E\u043C. \u041E\u0442\u0432\u0435\u0442 \u043F\u0440\u0438\u0434\u0451\u0442 \u0432 \u0442\u0438\u0448\u0438\u043D\u0435." }, "wheel": { "l": "\u041E\u0431\u0441\u0442\u043E\u044F\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u0430 \u0441\u0430\u043C\u0438 \u0441\u0434\u0432\u0438\u043D\u0443\u0442 \u0447\u0443\u0432\u0441\u0442\u0432\u043E. \u041E\u0442 \u0432\u0430\u0448\u0438\u0445 \u0440\u0435\u0447\u0435\u0439 \u0441\u0435\u0439\u0447\u0430\u0441 \u043C\u0430\u043B\u043E \u0447\u0442\u043E \u0437\u0430\u0432\u0438\u0441\u0438\u0442.", "w": "\u041F\u0435\u0440\u0435\u043C\u0435\u043D\u044B \u0438\u0434\u0443\u0442 \u043A \u043B\u0443\u0447\u0448\u0435\u043C\u0443. \u0421\u043E\u0433\u043B\u0430\u0448\u0430\u0439\u0442\u0435\u0441\u044C \u043D\u0430 \u043D\u043E\u0432\u043E\u0435, \u0441\u0442\u0430\u0440\u043E\u0435 \u0441\u0430\u043C\u043E \u043E\u0442\u043E\u0439\u0434\u0451\u0442.", "m": "\u0412\u043E\u0437\u043C\u043E\u0436\u043D\u043E\u0441\u0442\u044C \u043C\u043E\u0436\u0435\u0442 \u043F\u0440\u0438\u0439\u0442\u0438 \u0432\u043D\u0435\u0437\u0430\u043F\u043D\u043E. \u041D\u0435 \u0434\u0435\u0440\u0436\u0438\u0442\u0435\u0441\u044C \u0437\u0430 \u043F\u0440\u0435\u0436\u043D\u044E\u044E \u0441\u0445\u0435\u043C\u0443.", "a": "\u041D\u0435 \u0441\u043E\u043F\u0440\u043E\u0442\u0438\u0432\u043B\u044F\u0439\u0442\u0435\u0441\u044C \u043F\u0435\u0440\u0435\u043C\u0435\u043D\u0435. \u041E\u043D\u0430 \u0441\u0435\u0439\u0447\u0430\u0441 \u0437\u0430 \u0432\u0430\u0441." }, "justice": { "l": "\u041E\u0442\u0432\u0435\u0447\u0430\u044E\u0442 \u0442\u0430\u043A, \u043A\u0430\u043A \u0431\u044B\u043B\u043E \u043C\u0435\u0436\u0434\u0443 \u0432\u0430\u043C\u0438. \u0427\u0435\u0441\u0442\u043D\u043E\u0441\u0442\u044C \u0437\u0434\u0435\u0441\u044C \u0432\u0430\u0436\u043D\u0435\u0435 \u043A\u0440\u0430\u0441\u0438\u0432\u044B\u0445 \u043A\u043B\u044F\u0442\u0432.", "w": "\u0427\u0438\u0442\u0430\u0439\u0442\u0435 \u0434\u043E\u0433\u043E\u0432\u043E\u0440 \u0432\u043D\u0438\u043C\u0430\u0442\u0435\u043B\u044C\u043D\u043E. \u0427\u0435\u0441\u0442\u043D\u0430\u044F \u0441\u0434\u0435\u043B\u043A\u0430 \u0432\u0430\u0436\u043D\u0435\u0435 \u043A\u0440\u0430\u0441\u0438\u0432\u044B\u0445 \u043E\u0431\u0435\u0449\u0430\u043D\u0438\u0439.", "m": "\u0420\u0430\u0441\u043F\u043B\u0430\u0442\u0438\u0442\u0435\u0441\u044C \u0441 \u0434\u043E\u043B\u0433\u0430\u043C\u0438. \u0422\u043E\u0433\u0434\u0430 \u0438 \u0432\u0430\u043C \u0432\u0435\u0440\u043D\u0451\u0442\u0441\u044F.", "a": "\u041F\u043E\u0441\u0442\u0443\u043F\u0438\u0442\u0435 \u0447\u0435\u0441\u0442\u043D\u043E. \u042D\u0442\u043E \u0441\u0435\u0433\u043E\u0434\u043D\u044F \u0441\u0430\u043C\u044B\u0439 \u0432\u044B\u0433\u043E\u0434\u043D\u044B\u0439 \u0445\u043E\u0434." }, "hanged": { "l": "\u0421\u0435\u0439\u0447\u0430\u0441 \u043F\u0430\u0443\u0437\u0430. \u0427\u0435\u043B\u043E\u0432\u0435\u043A \u0441\u043C\u043E\u0442\u0440\u0438\u0442 \u0438\u043D\u0430\u0447\u0435 \u0438 \u043D\u0435 \u0434\u0432\u0438\u0436\u0435\u0442\u0441\u044F. \u042D\u0442\u043E \u0435\u0449\u0451 \u043D\u0435 \u043F\u0440\u0438\u0433\u043E\u0432\u043E\u0440.", "w": "\u0417\u0430\u0434\u0435\u0440\u0436\u043A\u0430 \u043D\u0435 \u043D\u0430\u043A\u0430\u0437\u0430\u043D\u0438\u0435. \u041F\u0435\u0440\u0435\u0441\u043C\u043E\u0442\u0440\u0438\u0442\u0435 \u0437\u0430\u0434\u0430\u0447\u0443, \u043F\u043E\u043A\u0430 \u043E\u043D\u0430 \u0441\u0442\u043E\u0438\u0442.", "m": "\u0417\u0430\u043C\u043E\u0440\u043E\u0437\u044C\u0442\u0435 \u043B\u0438\u0448\u043D\u0435\u0435. \u041F\u043E\u0434\u043F\u0438\u0441\u043A\u0438 \u0438 \u043C\u0435\u043B\u043A\u0438\u0435 \u0442\u0440\u0430\u0442\u044B \u043F\u0435\u0440\u0435\u0441\u043C\u043E\u0442\u0440\u0438\u0442\u0435 \u0441\u043F\u043E\u043A\u043E\u0439\u043D\u043E.", "a": "\u041E\u0442\u043F\u0443\u0441\u0442\u0438\u0442\u0435 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u044C \u0438 \u043F\u043E\u0441\u043C\u043E\u0442\u0440\u0438\u0442\u0435 \u043D\u0430 \u0434\u0435\u043B\u043E \u0441 \u0434\u0440\u0443\u0433\u043E\u0439 \u0441\u0442\u043E\u0440\u043E\u043D\u044B." }, "death": { "l": "\u0421\u0442\u0430\u0440\u044B\u0439 \u0441\u0446\u0435\u043D\u0430\u0440\u0438\u0439 \u043C\u0435\u0436\u0434\u0443 \u0432\u0430\u043C\u0438 \u043A\u043E\u043D\u0447\u0430\u0435\u0442\u0441\u044F. \u0422\u0435\u043C \u0436\u0435 \u0447\u0443\u0432\u0441\u0442\u0432\u043E\u043C, \u0447\u0442\u043E \u0431\u044B\u043B\u043E, \u0443\u0436\u0435 \u043D\u0435 \u0432\u0435\u0440\u043D\u0443\u0442\u044C.", "w": "\u042D\u0442\u0430\u043F \u0437\u0430\u043A\u0440\u044B\u0432\u0430\u0435\u0442\u0441\u044F: \u043F\u0440\u043E\u0435\u043A\u0442 \u0438\u043B\u0438 \u0440\u043E\u043B\u044C. \u0411\u043E\u044F\u0442\u044C\u0441\u044F \u043D\u0435\u0447\u0435\u0433\u043E, \u043F\u0440\u0435\u0436\u043D\u0435\u0435 \u0432\u0441\u0451 \u0440\u0430\u0432\u043D\u043E \u043D\u0435 \u0432\u0435\u0440\u043D\u0443\u0442\u044C.", "m": "\u0417\u0430\u043A\u0440\u043E\u0439\u0442\u0435 \u0441\u0442\u0430\u0440\u044B\u0435 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u0430. \u041E\u043D\u0438 \u0442\u044F\u043D\u0443\u0442 \u043D\u0430\u0437\u0430\u0434.", "a": "\u0417\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u0435 \u043E\u0434\u043D\u043E \u043E\u0442\u0436\u0438\u0432\u0448\u0435\u0435 \u0434\u0435\u043B\u043E. \u0421\u0440\u0430\u0437\u0443 \u0441\u0442\u0430\u043D\u0435\u0442 \u043B\u0435\u0433\u0447\u0435." }, "temperance": { "l": "\u0427\u0435\u043B\u043E\u0432\u0435\u043A \u0438\u0449\u0435\u0442 \u043C\u0435\u0440\u0443: \u043D\u0435 \u043A\u0438\u0434\u0430\u0442\u044C\u0441\u044F \u0438 \u043D\u0435 \u0437\u0430\u0436\u0438\u043C\u0430\u0442\u044C. \u0427\u0443\u0432\u0441\u0442\u0432\u043E \u0438\u0434\u0451\u0442 \u043F\u043E \u043A\u0430\u043F\u043B\u0435.", "w": "\u041D\u0435 \u043F\u0435\u0440\u0435\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u0439\u0442\u0435 \u0438 \u043D\u0435 \u0441\u0430\u0431\u043E\u0442\u0438\u0440\u0443\u0439\u0442\u0435. \u0421\u0435\u0440\u0435\u0434\u0438\u043D\u0430 \u0441\u0435\u0433\u043E\u0434\u043D\u044F \u0441\u0438\u043B\u044C\u043D\u0435\u0435 \u043A\u0440\u0430\u0439\u043D\u043E\u0441\u0442\u0438.", "m": "\u0418 \u043A\u043E\u043F\u0438\u0442\u0435, \u0438 \u0436\u0438\u0432\u0438\u0442\u0435. \u041A\u0440\u0430\u0439\u043D\u043E\u0441\u0442\u044C \u0432 \u043B\u044E\u0431\u0443\u044E \u0441\u0442\u043E\u0440\u043E\u043D\u0443 \u0441\u0435\u0439\u0447\u0430\u0441 \u0432\u0440\u0435\u0434\u043D\u0430.", "a": "\u041D\u0430\u0439\u0434\u0438\u0442\u0435 \u043C\u0435\u0440\u0443. \u041E\u043D\u0430 \u0441\u0435\u0439\u0447\u0430\u0441 \u0432\u0430\u0448 \u0441\u043E\u044E\u0437\u043D\u0438\u043A." }, "devil": { "l": "\u0422\u044F\u0433\u0430 \u0441\u0438\u043B\u044C\u043D\u0430\u044F: \u0441\u0442\u0440\u0430\u0441\u0442\u044C \u0438\u043B\u0438 \u0437\u0430\u0432\u0438\u0441\u0438\u043C\u043E\u0441\u0442\u044C. \u0421\u0432\u043E\u0431\u043E\u0434\u043D\u044B\u043C \u044D\u0442\u043E\u0442 \u0447\u0435\u043B\u043E\u0432\u0435\u043A \u0441\u0435\u0439\u0447\u0430\u0441 \u043D\u0435 \u0432\u044B\u0433\u043B\u044F\u0434\u0438\u0442.", "w": "\u041F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435, \u0447\u044C\u0438 \u044D\u0442\u043E \xAB\u043D\u0430\u0434\u043E\xBB. \u041A\u0430\u043F\u043A\u0430\u043D \u0447\u0443\u0436\u0438\u0445 \u043E\u0436\u0438\u0434\u0430\u043D\u0438\u0439 \u043B\u0435\u0433\u043A\u043E \u043F\u0440\u0438\u043D\u044F\u0442\u044C \u0437\u0430 \u0441\u0432\u043E\u0439 \u0434\u043E\u043B\u0433.", "m": "\u041A\u0440\u0435\u0434\u0438\u0442 \u0438 \u0438\u043C\u043F\u0443\u043B\u044C\u0441 \u0441\u0435\u0433\u043E\u0434\u043D\u044F \u043D\u0435 \u0434\u0440\u0443\u0437\u044C\u044F. \u0421\u043E\u0431\u043B\u0430\u0437\u043D \u0434\u043E\u0440\u043E\u0436\u0435, \u0447\u0435\u043C \u043A\u0430\u0436\u0435\u0442\u0441\u044F.", "a": "\u041D\u0430\u0437\u043E\u0432\u0438\u0442\u0435 \u0441\u0442\u0440\u0430\u0445 \u043F\u043E \u0438\u043C\u0435\u043D\u0438. \u041E\u043D \u0441\u0440\u0430\u0437\u0443 \u0441\u0442\u0430\u043D\u0435\u0442 \u043C\u0435\u043D\u044C\u0448\u0435." }, "tower": { "l": "\u041B\u043E\u0436\u043D\u043E\u0435 \u043C\u0435\u0436\u0434\u0443 \u0432\u0430\u043C\u0438 \u0440\u0443\u0448\u0438\u0442\u0441\u044F. \u041F\u0440\u0430\u0432\u0434\u0430 \u0432\u044B\u0439\u0434\u0435\u0442 \u0440\u0435\u0437\u043A\u043E, \u043D\u0435 \u043C\u044F\u0433\u043A\u043E.", "w": "\u0412\u0441\u0442\u0440\u044F\u0441\u043A\u0430 \u043E\u0441\u0432\u043E\u0431\u043E\u0434\u0438\u0442 \u043C\u0435\u0441\u0442\u043E. \u0427\u0438\u043D\u0438\u0442\u044C \u0440\u0443\u0448\u0430\u0449\u0435\u0435\u0441\u044F \u0431\u0435\u0441\u043F\u043E\u043B\u0435\u0437\u043D\u043E.", "m": "\u041C\u043E\u0436\u0435\u0442 \u0432\u044B\u0441\u043A\u043E\u0447\u0438\u0442\u044C \u043D\u0435\u043F\u0440\u0435\u0434\u0432\u0438\u0434\u0435\u043D\u043D\u043E\u0435. \u0414\u0435\u0440\u0436\u0438\u0442\u0435 \u043F\u043E\u0434\u0443\u0448\u043A\u0443 \u0438 \u043D\u0435 \u043F\u0430\u043D\u0438\u043A\u0443\u0439\u0442\u0435.", "a": "\u041E\u0442\u043E\u0439\u0434\u0438\u0442\u0435 \u043E\u0442 \u0442\u043E\u0433\u043E, \u0447\u0442\u043E \u043F\u0430\u0434\u0430\u0435\u0442. \u0421\u0442\u0440\u043E\u0438\u0442\u044C \u0431\u0443\u0434\u0435\u0442\u0435 \u043D\u0430 \u043F\u0440\u0430\u0432\u0434\u0435." }, "star": { "l": "\u041F\u043E\u0441\u043B\u0435 \u0442\u0440\u0443\u0434\u043D\u043E\u0433\u043E \u0441\u043D\u043E\u0432\u0430 \u0435\u0441\u0442\u044C \u043D\u0430\u0434\u0435\u0436\u0434\u0430. \u0427\u0435\u043B\u043E\u0432\u0435\u043A \u0445\u043E\u0447\u0435\u0442, \u0434\u0430\u0436\u0435 \u0435\u0441\u043B\u0438 \u0435\u0449\u0451 \u043C\u043E\u043B\u0447\u0438\u0442.", "w": "\u0414\u0435\u043B\u0430\u0439\u0442\u0435 \u0442\u043E, \u043E \u0447\u0451\u043C \u043C\u0435\u0447\u0442\u0430\u043B\u0438. \u0412\u0434\u043E\u0445\u043D\u043E\u0432\u0435\u043D\u0438\u0435 \u0441\u0435\u0439\u0447\u0430\u0441 \u0432\u0435\u0434\u0451\u0442 \u043B\u0443\u0447\u0448\u0435 \u043F\u043B\u0430\u043D\u0430.", "m": "\u041D\u0430\u0434\u0435\u044F\u0442\u044C\u0441\u044F \u043C\u043E\u0436\u043D\u043E, \u043D\u043E \u0441\u0435\u0433\u043E\u0434\u043D\u044F \u0432\u0435\u0447\u0435\u0440\u043E\u043C \u0434\u0435\u043D\u044C\u0433\u0438 \u0441\u0430\u043C\u0438 \u043D\u0435 \u043F\u0440\u0438\u0434\u0443\u0442. \u0415\u0441\u043B\u0438 \u0438 \u0431\u0443\u0434\u0435\u0442 \u043F\u0440\u0438\u0445\u043E\u0434, \u0442\u043E \u043F\u043E\u043D\u0435\u043C\u043D\u043E\u0433\u0443.", "a": "\u041F\u043E\u0437\u0432\u043E\u043B\u044C\u0442\u0435 \u0441\u0435\u0431\u0435 \u0441\u043D\u043E\u0432\u0430 \u0445\u043E\u0442\u0435\u0442\u044C. \u0421\u0438\u043B\u044B \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u044E\u0442\u0441\u044F." }, "moon": { "l": "\u0427\u0443\u0432\u0441\u0442\u0432\u0430 \u0433\u0440\u043E\u043C\u0447\u0435 \u0444\u0430\u043A\u0442\u043E\u0432, \u043A\u0440\u0443\u0433\u043E\u043C \u0442\u0443\u043C\u0430\u043D. \u0425\u043E\u043B\u043E\u0434 \u0438\u043B\u0438 \u0438\u0437\u043C\u0435\u043D\u0430 \u043C\u043E\u0433\u0443\u0442 \u043E\u043A\u0430\u0437\u0430\u0442\u044C\u0441\u044F \u0442\u0435\u043D\u044C\u044E.", "w": "\u0423\u0441\u043B\u043E\u0432\u0438\u044F \u043D\u0435\u044F\u0441\u043D\u044B. \u0423\u0442\u043E\u0447\u043D\u044F\u0439\u0442\u0435, \u043D\u0435 \u0434\u043E\u0434\u0443\u043C\u044B\u0432\u0430\u0439\u0442\u0435.", "m": "\u0427\u0438\u0442\u0430\u0439\u0442\u0435 \u043C\u0435\u043B\u043A\u0438\u0439 \u0448\u0440\u0438\u0444\u0442 \u0434\u0432\u0430\u0436\u0434\u044B. \u0422\u0443\u043C\u0430\u043D \u043D\u0430 \u0434\u0435\u043D\u044C\u0433\u0430\u0445 \u0434\u043E\u0440\u043E\u0433\u043E \u0441\u0442\u043E\u0438\u0442.", "a": "\u041D\u0435 \u0440\u0435\u0448\u0430\u0439\u0442\u0435 \u043D\u043E\u0447\u044C\u044E. \u0423\u0442\u0440\u043E\u043C \u0441\u0442\u0430\u043D\u0435\u0442 \u0432\u0438\u0434\u043D\u043E." }, "sun": { "l": "\u0417\u0434\u0435\u0441\u044C \u044F\u0441\u043D\u043E \u0438 \u0442\u0435\u043F\u043B\u043E. \u041F\u0440\u044F\u0442\u0430\u0442\u044C \u043D\u0435\u0447\u0435\u0433\u043E: \u0447\u0435\u043B\u043E\u0432\u0435\u043A\u0443 \u0441 \u0432\u0430\u043C\u0438 \u0445\u043E\u0440\u043E\u0448\u043E \u043D\u0430 \u0441\u0432\u0435\u0442\u0443.", "w": "\u0412\u0430\u0441 \u0437\u0430\u043C\u0435\u0442\u044F\u0442. \u0412\u044B\u0445\u043E\u0434\u0438\u0442\u0435 \u0432\u043F\u0435\u0440\u0451\u0434, \u0443\u0441\u043F\u0435\u0445 \u0441\u0435\u0439\u0447\u0430\u0441 \u043D\u0435 \u043F\u0440\u044F\u0447\u0435\u0442\u0441\u044F.", "m": "\u041C\u043E\u0436\u043D\u043E \u0438 \u0437\u0430\u0440\u0430\u0431\u043E\u0442\u0430\u0442\u044C, \u0438 \u043F\u043E\u0442\u0440\u0430\u0442\u0438\u0442\u044C \u0441 \u0440\u0430\u0434\u043E\u0441\u0442\u044C\u044E. \u041F\u0435\u0440\u0438\u043E\u0434 \u0449\u0435\u0434\u0440\u044B\u0439.", "a": "\u0412\u043E\u0437\u044C\u043C\u0438\u0442\u0435\u0441\u044C \u0437\u0430 \u0442\u043E, \u0447\u0435\u0433\u043E \u0431\u043E\u044F\u043B\u0438\u0441\u044C. \u041E\u043D\u043E \u043E\u043A\u0430\u0436\u0435\u0442\u0441\u044F \u043F\u0440\u043E\u0449\u0435." }, "judgement": { "l": "\u041F\u043E\u0440\u0430 \u0437\u0430\u043A\u0440\u044B\u0442\u044C \u0441\u0442\u0430\u0440\u044B\u0439 \u0441\u0447\u0451\u0442: \u043F\u0440\u043E\u0441\u0442\u0438\u0442\u044C, \u0432\u0435\u0440\u043D\u0443\u0442\u044C\u0441\u044F \u0438\u043B\u0438 \u043D\u0430\u0437\u0432\u0430\u0442\u044C \u043A\u043E\u043D\u0435\u0446. \u042D\u0442\u043E \u043D\u0435 \u0432\u0441\u043F\u044B\u0448\u043A\u0430 \u043D\u043E\u0432\u043E\u0433\u043E \u0443\u0432\u043B\u0435\u0447\u0435\u043D\u0438\u044F.", "w": "\u041F\u0440\u0438\u0437\u0432\u0430\u043D\u0438\u0435 \u043D\u0430\u043F\u043E\u043C\u0438\u043D\u0430\u0435\u0442 \u043E \u0441\u0435\u0431\u0435. \u041E\u0442\u043A\u043B\u0438\u043A\u043D\u0438\u0442\u0435\u0441\u044C, \u043E\u0442\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0442\u044C \u0431\u043E\u043B\u044C\u0448\u0435 \u043D\u0435\u043B\u044C\u0437\u044F.", "m": "\u0421\u0442\u0430\u0440\u043E\u0435 \u0432\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0438\u043B\u0438 \u0434\u043E\u043B\u0433 \u043C\u043E\u0433\u0443\u0442 \u0432\u0435\u0440\u043D\u0443\u0442\u044C\u0441\u044F. \u041D\u0435 \u043F\u0440\u043E\u043F\u0443\u0441\u0442\u0438\u0442\u0435 \u044D\u0442\u043E\u0442 \u0437\u043E\u0432.", "a": "\u041E\u0442\u0432\u0435\u0442\u044C\u0442\u0435 \u043D\u0430 \u0442\u043E, \u0447\u0442\u043E \u0434\u0430\u0432\u043D\u043E \u0441\u043B\u044B\u0448\u0438\u0442\u0435." }, "world": { "l": "\u041C\u0435\u0436\u0434\u0443 \u0432\u0430\u043C\u0438 \u043C\u043E\u0436\u0435\u0442 \u0437\u0430\u043A\u0440\u044B\u0442\u044C\u0441\u044F \u0446\u0435\u043B\u044B\u0439 \u043A\u0440\u0443\u0433. \u0427\u0443\u0432\u0441\u0442\u0432\u043E \u0446\u0435\u043B\u044C\u043D\u043E\u0435, \u043D\u0435 \u043E\u0431\u0440\u044B\u0432\u043E\u043A.", "w": "\u041F\u0440\u043E\u0435\u043A\u0442 \u0434\u043E\u0445\u043E\u0434\u0438\u0442 \u0434\u043E \u0444\u0438\u043D\u0430\u043B\u0430. \u0421\u043E\u0431\u0435\u0440\u0438\u0442\u0435 \u0437\u0430\u0441\u043B\u0443\u0436\u0435\u043D\u043D\u043E\u0435, \u043D\u0435 \u0443\u0431\u0435\u0433\u0430\u0439\u0442\u0435 \u0432 \u043D\u043E\u0432\u043E\u0435 \u0440\u0430\u043D\u044C\u0448\u0435 \u0432\u0440\u0435\u043C\u0435\u043D\u0438.", "m": "\u0426\u0435\u043B\u044C \u043F\u043E \u0441\u0443\u043C\u043C\u0435 \u0434\u043E\u0441\u0442\u0438\u0433\u043D\u0443\u0442\u0430. \u041C\u043E\u0436\u043D\u043E \u0441\u0442\u0430\u0432\u0438\u0442\u044C \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0443\u044E, \u0431\u043E\u043B\u044C\u0448\u0435.", "a": "\u0417\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u0435 \u0438 \u043E\u0442\u043C\u0435\u0442\u044C\u0442\u0435. \u0412\u044B \u0434\u043E\u0448\u043B\u0438." }, "cups_ace": { "l": "\u0420\u043E\u0436\u0434\u0430\u0435\u0442\u0441\u044F \u043D\u043E\u0432\u043E\u0435 \u0447\u0443\u0432\u0441\u0442\u0432\u043E. \u041E\u043D\u043E \u0435\u0449\u0451 \u0442\u043E\u043D\u043A\u043E\u0435: \u0447\u0435\u043B\u043E\u0432\u0435\u043A \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442\u0441\u044F, \u0430 \u043D\u0435 \u043E\u0431\u0435\u0449\u0430\u0435\u0442 \u0434\u043E\u043C.", "w": "\u0411\u0435\u0437 \u0436\u0438\u0432\u043E\u0433\u043E \u0438\u043D\u0442\u0435\u0440\u0435\u0441\u0430 \u0434\u0435\u043B\u043E \u043D\u0435 \u0432\u0441\u0445\u043E\u0434\u0438\u0442. \u041E\u043A\u043B\u0430\u0434 \u043E\u0442 \u0441\u043A\u0443\u043A\u0438 \u0441\u0430\u043C \u043D\u0435 \u0432\u044B\u0440\u0430\u0441\u0442\u0435\u0442.", "m": "\u0411\u043E\u043B\u044C\u0448\u043E\u0439 \u0441\u0443\u043C\u043C\u044B \u0437\u0434\u0435\u0441\u044C \u043D\u0435\u0442. \u0415\u0441\u043B\u0438 \u0434\u0435\u043D\u044C\u0433\u0438 \u0438 \u043F\u0440\u0438\u0434\u0443\u0442, \u0442\u043E \u0447\u0435\u0440\u0435\u0437 \u043F\u043E\u0434\u0430\u0440\u043E\u043A \u0438\u043B\u0438 \u0442\u0451\u043F\u043B\u043E\u0435 \u0434\u0435\u043B\u043E, \u043D\u0435 \u0447\u0435\u0440\u0435\u0437 \u0440\u0430\u0441\u0447\u0451\u0442.", "a": "\u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435\u0441\u044C \u0442\u043E\u043C\u0443, \u0447\u0442\u043E \u0442\u043E\u043B\u044C\u043A\u043E \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442\u0441\u044F." }, "cups_2": { "l": "\u042D\u0442\u043E\u0442 \u0447\u0435\u043B\u043E\u0432\u0435\u043A \u043E\u0442\u0432\u0435\u0447\u0430\u0435\u0442 \u0432\u0437\u0430\u0438\u043C\u043D\u043E\u0441\u0442\u044C\u044E. \u0413\u043E\u0442\u043E\u0432 \u043A \u043E\u0431\u043C\u0435\u043D\u0443, \u043D\u0435 \u043A \u043F\u043E\u0433\u043E\u043D\u0435 \u0432 \u043E\u0434\u043D\u0443 \u0441\u0442\u043E\u0440\u043E\u043D\u0443.", "w": "\u041E\u0434\u0438\u043D \u0445\u043E\u0440\u043E\u0448\u0438\u0439 \u043F\u0430\u0440\u0442\u043D\u0451\u0440 \u043B\u0443\u0447\u0448\u0435 \u0434\u0435\u0441\u044F\u0442\u0438 \u0445\u043E\u043B\u043E\u0434\u043D\u044B\u0445 \u043A\u043B\u0438\u0435\u043D\u0442\u043E\u0432. \u0421\u043E\u044E\u0437 \u0441\u0435\u0439\u0447\u0430\u0441 \u0441\u0438\u043B\u044C\u043D\u0435\u0435 \u0433\u043E\u043D\u043A\u0438.", "m": "\u0421\u0434\u0435\u043B\u043A\u0430 \u0436\u0438\u0432\u0430, \u043A\u043E\u0433\u0434\u0430 \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u044E\u0442 \u043E\u0431\u0430. \u0427\u0435\u0441\u0442\u043D\u044B\u0439 \u043E\u0431\u043C\u0435\u043D \u0432\u0430\u0436\u043D\u0435\u0435 \u0440\u0430\u0437\u043E\u0432\u043E\u0439 \u0432\u044B\u0433\u043E\u0434\u044B.", "a": "\u041F\u043E\u0441\u043C\u043E\u0442\u0440\u0438\u0442\u0435, \u0442\u044F\u043D\u0435\u0442\u0441\u044F \u043B\u0438 \u0440\u0443\u043A\u0430 \u043D\u0430\u0432\u0441\u0442\u0440\u0435\u0447\u0443. \u041F\u043E\u0442\u043E\u043C \u0440\u0435\u0448\u0430\u0439\u0442\u0435, \u0442\u044F\u043D\u0443\u0442\u044C \u043B\u0438 \u0441\u0432\u043E\u044E." }, "cups_3": { "l": "\u041B\u0435\u0433\u0447\u0435 \u043D\u0430 \u043B\u044E\u0434\u044F\u0445, \u0447\u0435\u043C \u0442\u0435\u0442-\u0430-\u0442\u0435\u0442. \u0420\u0430\u0434\u043E\u0441\u0442\u044C \u043E\u0431\u0449\u0430\u044F, \u0442\u0430\u0439\u043D\u043E\u0433\u043E \u043F\u0440\u0438\u0437\u043D\u0430\u043D\u0438\u044F \u0437\u0434\u0435\u0441\u044C \u043D\u0435\u0442.", "w": "\u041A\u043E\u043C\u0430\u043D\u0434\u0430 \u0438 \u043F\u0440\u043E\u0441\u0442\u043E\u0439 \u0440\u0430\u0437\u0433\u043E\u0432\u043E\u0440 \u0440\u0435\u0448\u0430\u0442 \u0431\u043E\u043B\u044C\u0448\u0435 \u0441\u043E\u0432\u0435\u0449\u0430\u043D\u0438\u044F.", "m": "\u0422\u0440\u0430\u0442\u0430 \u043D\u0430 \u043B\u044E\u0434\u0435\u0439 \u0432\u0435\u0440\u043D\u0451\u0442\u0441\u044F \u0440\u0430\u0434\u043E\u0441\u0442\u044C\u044E. \u0421\u0435\u0439\u0447\u0430\u0441 \u044D\u0442\u043E \u043D\u0435 \u043F\u0443\u0441\u0442\u043E\u0439 \u0440\u0430\u0441\u0445\u043E\u0434.", "a": "\u0421\u043E\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u0432\u043E\u0438\u0445. \u041E\u0442\u0432\u0435\u0442 \u043F\u0440\u0438\u0434\u0451\u0442 \u0447\u0435\u0440\u0435\u0437 \u043E\u0431\u0449\u0435\u043D\u0438\u0435." }, "cups_4": { "l": "\u041F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u043D\u043E\u0435 \u043D\u0435 \u0440\u0430\u0434\u0443\u0435\u0442. \u0427\u0435\u043B\u043E\u0432\u0435\u043A \u0441\u043C\u043E\u0442\u0440\u0438\u0442 \u043C\u0438\u043C\u043E \u0442\u043E\u0433\u043E, \u0447\u0442\u043E \u0432\u044B \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0435 \u0433\u043B\u0430\u0432\u043D\u044B\u043C.", "w": "\u0421\u043A\u0443\u043A\u0430 \u0437\u0430\u0441\u0442\u0438\u043B\u0430\u0435\u0442 \u0433\u043B\u0430\u0437\u0430. \u0420\u044F\u0434\u043E\u043C \u0443\u0436\u0435 \u0435\u0441\u0442\u044C \u043D\u043E\u0432\u043E\u0435 \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u0438\u0435, \u0435\u0433\u043E \u043F\u0440\u043E\u0441\u0442\u043E \u043D\u0435 \u0437\u0430\u043C\u0435\u0447\u0430\u044E\u0442.", "m": "\u0428\u0430\u043D\u0441 \u0441\u043F\u043E\u043A\u043E\u0439\u043D\u044B\u0439 \u0438 \u043D\u0435\u044F\u0440\u043A\u0438\u0439. \u0415\u0433\u043E \u043B\u0435\u0433\u043A\u043E \u043F\u0440\u043E\u043F\u0443\u0441\u0442\u0438\u0442\u044C.", "a": "\u041F\u043E\u0434\u043D\u0438\u043C\u0438\u0442\u0435 \u0432\u0437\u0433\u043B\u044F\u0434. \u0412\u0430\u043C \u0443\u0436\u0435 \u043F\u0440\u043E\u0442\u044F\u043D\u0443\u043B\u0438 \u0442\u043E, \u0447\u0442\u043E \u043D\u0443\u0436\u043D\u043E." }, "cups_5": { "l": "\u0427\u0435\u043B\u043E\u0432\u0435\u043A \u0441\u043C\u043E\u0442\u0440\u0438\u0442 \u043D\u0430 \u043F\u0440\u043E\u043B\u0438\u0442\u043E\u0435 \u0438 \u043E\u0431\u0438\u0436\u0430\u0435\u0442\u0441\u044F. \u0418\u0437-\u0437\u0430 \u044D\u0442\u043E\u0433\u043E \u043C\u043E\u0436\u0435\u0442 \u043D\u0435 \u0432\u0438\u0434\u0435\u0442\u044C, \u0447\u0442\u043E \u0440\u044F\u0434\u043E\u043C \u0435\u0449\u0451 \u0436\u0438\u0432\u043E.", "w": "\u041D\u0435\u0443\u0434\u0430\u0447\u0430 \u0447\u0430\u0441\u0442\u0438\u0447\u043D\u0430\u044F. \u0414\u0432\u0435 \u0447\u0430\u0448\u0438 \u0446\u0435\u043B\u044B, \u0441\u0442\u0440\u043E\u0439\u0442\u0435 \u043D\u0430 \u043D\u0438\u0445, \u043D\u0435 \u043D\u0430 \u043F\u0440\u043E\u043B\u0438\u0442\u043E\u043C.", "m": "\u041F\u043E\u0442\u0435\u0440\u044F \u043C\u0435\u043D\u044C\u0448\u0435, \u0447\u0435\u043C \u043A\u0430\u0436\u0435\u0442\u0441\u044F. \u041F\u043E\u0441\u0447\u0438\u0442\u0430\u0439\u0442\u0435, \u0447\u0442\u043E \u043E\u0441\u0442\u0430\u043B\u043E\u0441\u044C.", "a": "\u041E\u0442\u043E\u0440\u0432\u0438\u0442\u0435 \u0432\u0437\u0433\u043B\u044F\u0434 \u043E\u0442 \u043F\u0440\u043E\u043B\u0438\u0442\u043E\u0433\u043E. \u0423 \u0432\u0430\u0441 \u0435\u0449\u0451 \u043C\u043D\u043E\u0433\u043E\u0435 \u0446\u0435\u043B\u043E." }, "cups_6": { "l": "\u0422\u044F\u043D\u0435\u0442 \u0442\u0451\u043F\u043B\u043E\u0435 \u043F\u0440\u043E\u0448\u043B\u043E\u0435. \u041F\u043E\u043C\u043D\u044F\u0442 \u043F\u0440\u043E\u0441\u0442\u043E\u0435 \u0438 \u0434\u043E\u0431\u0440\u043E\u0435, \u043D\u0435 \u0441\u0435\u0433\u043E\u0434\u043D\u044F\u0448\u043D\u0438\u0435 \u0438\u0433\u0440\u044B.", "w": "\u0421\u0442\u0430\u0440\u044B\u0435 \u0441\u0432\u044F\u0437\u0438 \u0438\u043B\u0438 \u0434\u0435\u0442\u0441\u043A\u0430\u044F \u043C\u0435\u0447\u0442\u0430 \u043F\u043E\u0434\u0441\u043A\u0430\u0436\u0443\u0442 \u0445\u043E\u0434. \u041D\u043E\u0432\u043E\u0435 \u0440\u0430\u0434\u0438 \u043D\u043E\u0432\u0438\u0437\u043D\u044B \u0441\u0435\u0439\u0447\u0430\u0441 \u0441\u043B\u0430\u0431\u0435\u0435.", "m": "\u041C\u043E\u0436\u0435\u0442 \u043F\u0440\u0438\u0439\u0442\u0438 \u043F\u043E\u0434\u0430\u0440\u043E\u043A, \u0432\u043E\u0437\u0432\u0440\u0430\u0442 \u0438\u043B\u0438 \u043F\u043E\u043C\u043E\u0449\u044C \u0438\u0437 \u043F\u0440\u043E\u0448\u043B\u043E\u0433\u043E.", "a": "\u0415\u0441\u043B\u0438 \u043F\u0440\u043E\u0448\u043B\u043E\u0435 \u0441\u0430\u043C\u043E \u0441\u0442\u0443\u0447\u0438\u0442\u0441\u044F \u2014 \u043E\u0442\u0432\u0435\u0442\u044C\u0442\u0435. \u0417\u0432\u043E\u043D\u0438\u0442\u044C \u043D\u0430 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0443 \u043D\u0435 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E." }, "cups_7": { "l": "\u0412 \u0433\u043E\u043B\u043E\u0432\u0435 \u043C\u043D\u043E\u0433\u043E \u043A\u0430\u0440\u0442\u0438\u043D\u043E\u043A. \u0412\u044B\u0431\u0438\u0440\u0430\u044E\u0442 \u043E\u0431\u0440\u0430\u0437, \u043D\u0435 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E \u0432\u0430\u0441 \u043D\u0430\u0441\u0442\u043E\u044F\u0449\u0438\u0445.", "w": "\u0412\u0430\u0440\u0438\u0430\u043D\u0442\u043E\u0432 \u043C\u043D\u043E\u0433\u043E, \u043D\u0430\u0441\u0442\u043E\u044F\u0449\u0438\u0439 \u043E\u0434\u0438\u043D. \u041F\u0440\u043E\u0432\u0435\u0440\u044F\u0439\u0442\u0435 \u0434\u0435\u043B\u043E\u043C, \u043D\u0435 \u0431\u043B\u0435\u0441\u043A\u043E\u043C.", "m": "\xAB\u0417\u043E\u043B\u043E\u0442\u044B\u0435 \u0433\u043E\u0440\u044B\xBB \u043E\u0431\u043C\u0430\u043D\u0447\u0438\u0432\u044B. \u0421\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u0434\u0432\u0430\u0436\u0434\u044B.", "a": "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043E\u0434\u043D\u043E \u0436\u0435\u043B\u0430\u043D\u0438\u0435 \u0438 \u0441\u0434\u0435\u043B\u0430\u0439\u0442\u0435 \u043F\u043E \u043D\u0435\u043C\u0443 \u0448\u0430\u0433." }, "cups_8": { "l": "\u0421\u0435\u0440\u0434\u0446\u0435 \u0443\u0436\u0435 \u0443\u0445\u043E\u0434\u0438\u0442 \u0442\u0443\u0434\u0430, \u0433\u0434\u0435 \u0433\u043B\u0443\u0431\u0436\u0435. \u0412\u043B\u043E\u0436\u0435\u043D\u043E \u043C\u043D\u043E\u0433\u043E, \u0438 \u0432\u0441\u0451 \u0440\u0430\u0432\u043D\u043E \u0442\u044F\u043D\u0435\u0442 \u043F\u0440\u043E\u0447\u044C.", "w": "\u041F\u043E\u0440\u0430 \u043E\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u0442\u043E, \u0447\u0442\u043E \u043F\u0435\u0440\u0435\u0441\u0442\u0430\u043B\u043E \u043A\u043E\u0440\u043C\u0438\u0442\u044C. \u0416\u0430\u043B\u043A\u043E, \u043D\u043E \u0434\u0443\u0448\u0430 \u0443\u0436\u0435 \u043D\u0435 \u0437\u0434\u0435\u0441\u044C.", "m": "\u041B\u0443\u0447\u0448\u0435 \u043C\u0435\u043D\u044C\u0448\u0435, \u043D\u043E \u0432 \u0441\u043E\u0433\u043B\u0430\u0441\u0438\u0438 \u0441 \u0441\u043E\u0431\u043E\u0439. \u0422\u044F\u043D\u0443\u0442\u044C \u0447\u0443\u0436\u043E\u0435 \u0440\u0430\u0434\u0438 \u0441\u0443\u043C\u043C\u044B \u043D\u0435 \u0441\u0442\u043E\u0438\u0442.", "a": "\u0418\u0434\u0438\u0442\u0435 \u0442\u0443\u0434\u0430, \u0433\u0434\u0435 \u0433\u043B\u0443\u0431\u0436\u0435. \u0414\u0430\u0436\u0435 \u0435\u0441\u043B\u0438 \u0437\u0434\u0435\u0441\u044C \u0443\u0436\u0435 \u0432\u043B\u043E\u0436\u0435\u043D\u043E \u043C\u043D\u043E\u0433\u043E." }, "cups_9": { "l": "\u0427\u0435\u043B\u043E\u0432\u0435\u043A \u0434\u043E\u0432\u043E\u043B\u0435\u043D \u0441\u043E\u0431\u043E\u0439. \u042D\u0442\u043E \u0441\u0432\u0435\u0442\u0438\u0442, \u043D\u043E \u043D\u0435 \u0437\u043D\u0430\u0447\u0438\u0442, \u0447\u0442\u043E \u0437\u0430\u0433\u0430\u0434\u0430\u043D\u043D\u043E\u0435 \u0436\u0435\u043B\u0430\u043D\u0438\u0435 \u2014 \u0432\u044B.", "w": "\u0416\u0435\u043B\u0430\u043D\u0438\u0435 \u043F\u043E \u0440\u0430\u0431\u043E\u0442\u0435 \u0431\u043B\u0438\u0436\u0435, \u0447\u0435\u043C \u043A\u0430\u0436\u0435\u0442\u0441\u044F. \u041F\u0440\u043E\u0441\u0438\u0442\u0435 \u043F\u043E \u0434\u0435\u043B\u0443, \u043D\u0435 \u0432\u0434\u0440\u0443\u0433 \u043F\u043E\u0432\u0435\u0437\u0451\u0442.", "m": "\u041F\u0435\u0440\u0438\u043E\u0434 \u0443\u0434\u0430\u0447\u043D\u044B\u0439 \u0434\u043B\u044F \u0436\u0435\u043B\u0430\u043D\u043D\u043E\u0433\u043E, \u0435\u0441\u043B\u0438 \u043E\u043D\u043E \u043F\u043E \u043A\u0430\u0440\u043C\u0430\u043D\u0443. \u0412 \u0434\u043E\u043B\u0433 \u043D\u0430 \u0441\u0447\u0430\u0441\u0442\u044C\u0435 \u043D\u0435 \u0431\u0435\u0440\u0438\u0442\u0435.", "a": "\u041D\u0430\u0437\u043E\u0432\u0438\u0442\u0435, \u0447\u0435\u0433\u043E \u0445\u043E\u0442\u0438\u0442\u0435, \u043F\u043E-\u043D\u0430\u0441\u0442\u043E\u044F\u0449\u0435\u043C\u0443." }, "cups_10": { "l": "\u0412\u0438\u0434\u044F\u0442 \u0432\u0430\u0441 \u0432 \u0434\u043E\u043C\u0435 \u0438 \u0432 \u043E\u0431\u0449\u0435\u043C \u043A\u0440\u0443\u0433\u0435. \u0422\u0430\u0439\u043D\u044B\u0439 \u0440\u043E\u043C\u0430\u043D \u044D\u0442\u043E\u043C\u0443 \u0447\u0435\u043B\u043E\u0432\u0435\u043A\u0443 \u043D\u0435 \u043D\u0443\u0436\u0435\u043D.", "w": "\u041F\u043E\u0431\u0435\u0434\u0430 \u043E\u0431\u0449\u0430\u044F. \u041F\u0440\u0430\u0437\u0434\u043D\u0443\u0439\u0442\u0435 \u0441 \u0442\u0435\u043C\u0438, \u043A\u0442\u043E \u0442\u044F\u043D\u0443\u043B \u0432\u043C\u0435\u0441\u0442\u0435.", "m": "\u0414\u043E\u0441\u0442\u0430\u0442\u043E\u043A \u043D\u0430 \u0431\u043B\u0438\u0437\u043A\u0438\u0445. \u041F\u043E\u0442\u0440\u0430\u0442\u044C\u0442\u0435 \u043D\u0430 \u0434\u043E\u043C \u0438 \u0440\u0430\u0434\u043E\u0441\u0442\u044C, \u043D\u0435 \u043D\u0430 \u0432\u0438\u0442\u0440\u0438\u043D\u0443.", "a": "\u041E\u0433\u043B\u044F\u043D\u0438\u0442\u0435\u0441\u044C. \u0422\u043E \u0441\u0447\u0430\u0441\u0442\u044C\u0435, \u043A\u043E\u0442\u043E\u0440\u043E\u0435 \u0436\u0434\u0430\u043B\u0438 \u043F\u043E\u0442\u043E\u043C, \u0443\u0436\u0435 \u0440\u044F\u0434\u043E\u043C." }, "cups_page": { "l": "\u0415\u0441\u0442\u044C \u0440\u043E\u0431\u043A\u0438\u0439 \u0437\u043D\u0430\u043A: \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u0435, \u043A\u043E\u043C\u043F\u043B\u0438\u043C\u0435\u043D\u0442. \u042D\u0442\u043E \u0432\u0435\u0441\u0442\u043E\u0447\u043A\u0430, \u043D\u0435 \u0434\u043E\u0433\u043E\u0432\u043E\u0440.", "w": "\u0423\u0447\u0438\u0442\u0435\u0441\u044C \u043C\u044F\u0433\u043A\u043E. \u0418\u043D\u0442\u0435\u0440\u0435\u0441 \u0441\u0435\u0439\u0447\u0430\u0441 \u0432\u0430\u0436\u043D\u0435\u0435 \u0441\u0440\u0430\u0437\u0443 \u043F\u043E\u043A\u0430\u0437\u0430\u0442\u044C \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442.", "m": "\u041F\u0440\u0438\u0434\u0451\u0442 \u043D\u0435\u0431\u043E\u043B\u044C\u0448\u0430\u044F, \u043D\u043E \u043F\u0440\u0438\u044F\u0442\u043D\u0430\u044F \u043D\u043E\u0432\u043E\u0441\u0442\u044C \u043F\u043E \u0434\u0435\u043D\u044C\u0433\u0430\u043C.", "a": "\u0417\u0430\u043C\u0435\u0442\u044C\u0442\u0435 \u043C\u0430\u043B\u0435\u043D\u044C\u043A\u0438\u0439 \u0437\u043D\u0430\u043A. \u041E\u0442\u0432\u0435\u0442\u0438\u0442\u044C \u0442\u0435\u043C \u0436\u0435 \u043C\u043E\u0436\u043D\u043E, \u0441\u0446\u0435\u043D\u0443 \u0440\u0430\u043D\u043E." }, "cups_knight": { "l": "\u0420\u043E\u043C\u0430\u043D\u0442\u0438\u0447\u043D\u044B\u0439 \u0436\u0435\u0441\u0442 \u0443\u0436\u0435 \u0432 \u043F\u0443\u0442\u0438. \u0421\u043C\u043E\u0442\u0440\u0438\u0442\u0435, \u0441\u0442\u043E\u0438\u0442 \u043B\u0438 \u0437\u0430 \u043D\u0438\u043C \u0434\u0435\u043B\u043E \u0438\u043B\u0438 \u0442\u043E\u043B\u044C\u043A\u043E \u043A\u0440\u0430\u0441\u0438\u0432\u044B\u0439 \u0437\u0430\u0445\u043E\u0434.", "w": "\u041F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0443\u0436\u0435 \u0435\u0434\u0435\u0442. \u0412\u044B\u0441\u043B\u0443\u0448\u0430\u0439\u0442\u0435 \u0441\u043F\u043E\u043A\u043E\u0439\u043D\u043E, \u043D\u0435 \u0445\u0432\u0430\u0442\u0430\u0439\u0442\u0435 \u043D\u0430 \u043B\u0435\u0442\u0443.", "m": "\u0414\u0435\u043D\u044C\u0433\u0438 \u043C\u043E\u0433\u0443\u0442 \u043F\u0440\u0438\u0439\u0442\u0438 \u0447\u0435\u0440\u0435\u0437 \u0442\u0432\u043E\u0440\u0447\u0435\u0441\u0442\u0432\u043E \u0438\u043B\u0438 \u043F\u0440\u0438\u044F\u0442\u043D\u043E\u0435 \u0434\u0435\u043B\u043E.", "a": "\u0414\u0435\u0439\u0441\u0442\u0432\u0443\u0439\u0442\u0435 \u043A\u0440\u0430\u0441\u0438\u0432\u043E \u0438 \u043D\u0435\u0442\u043E\u0440\u043E\u043F\u043B\u0438\u0432\u043E." }, "cups_queen": { "l": "\u0427\u0435\u043B\u043E\u0432\u0435\u043A \u0447\u0443\u0432\u0441\u0442\u0432\u0443\u0435\u0442 \u0432\u0430\u0441 \u0442\u043E\u043D\u043A\u043E. \u042D\u0442\u043E \u0435\u0433\u043E \u0434\u0430\u0440, \u043D\u0435 \u0432\u0430\u0448\u0430 \u0440\u0430\u0431\u043E\u0442\u0430 \u0432\u0441\u0435\u0445 \u0441\u043F\u0430\u0441\u0430\u0442\u044C.", "w": "\u0427\u0443\u0442\u044C\u0451 \u043E \u043B\u044E\u0434\u044F\u0445 \u0441\u0435\u0439\u0447\u0430\u0441 \u0442\u043E\u0447\u043D\u0435\u0435 \u0442\u0430\u0431\u043B\u0438\u0446. \u0421\u043B\u0443\u0448\u0430\u0439\u0442\u0435 \u0435\u0433\u043E.", "m": "\u041A\u043B\u0430\u0434\u0438\u0442\u0435 \u0442\u0443\u0434\u0430, \u0433\u0434\u0435 \u0441\u043F\u043E\u043A\u043E\u0439\u043D\u043E. \u041F\u0430\u043D\u0438\u043A\u0430 \u0438 \u0447\u0443\u0436\u043E\u0439 \u0436\u0430\u0440 \u2014 \u043F\u043B\u043E\u0445\u0438\u0435 \u0441\u043E\u0432\u0435\u0442\u0447\u0438\u043A\u0438.", "a": "\u0411\u0435\u0440\u0435\u0433\u0438\u0442\u0435 \u0441\u0432\u043E\u0451 \u0441\u0435\u0440\u0434\u0446\u0435. \u041E\u043D\u043E \u0441\u0435\u0439\u0447\u0430\u0441 \u043A\u043E\u043C\u043F\u0430\u0441." }, "cups_king": { "l": "\u0427\u0443\u0432\u0441\u0442\u0432\u043E \u0434\u0435\u0440\u0436\u0430\u0442 \u0441\u043F\u043E\u043A\u043E\u0439\u043D\u043E, \u043F\u043E-\u0432\u0437\u0440\u043E\u0441\u043B\u043E\u043C\u0443. \u0422\u043E\u043D\u0443\u0442\u044C \u0432 \u043D\u0451\u043C \u044D\u0442\u043E\u0442 \u0447\u0435\u043B\u043E\u0432\u0435\u043A \u043D\u0435 \u0441\u0442\u0430\u043D\u0435\u0442.", "w": "\u0421 \u043B\u044E\u0434\u044C\u043C\u0438 \u0440\u0435\u0448\u0430\u0435\u0442 \u0441\u043F\u043E\u043A\u043E\u0439\u0441\u0442\u0432\u0438\u0435, \u043D\u0435 \u0440\u0435\u0433\u043B\u0430\u043C\u0435\u043D\u0442. \u0414\u0435\u0440\u0436\u0438\u0442\u0435 \u0441\u0435\u0431\u044F.", "m": "\u041D\u0443\u0436\u043D\u044B \u0441\u043F\u043E\u043A\u043E\u0439\u043D\u044B\u0435 \u0446\u0438\u0444\u0440\u044B, \u043D\u0435 \u0432\u0441\u043F\u044B\u0448\u043A\u0430. \u041F\u0430\u043D\u0438\u043A\u0430 \u0441\u0443\u043C\u043C\u0443 \u043D\u0435 \u0443\u0432\u0435\u043B\u0438\u0447\u0438\u0442.", "a": "\u041E\u0442\u0432\u0435\u0442\u044C\u0442\u0435 \u0441\u043F\u043E\u043A\u043E\u0439\u043D\u043E, \u043D\u0435 \u0441\u0433\u043E\u0440\u044F\u0447\u0430. \u0412\u044B \u044D\u0442\u043E \u0443\u043C\u0435\u0435\u0442\u0435." }, "wands_ace": { "l": "\u0412\u0441\u043F\u044B\u0445\u043D\u0443\u043B\u0430 \u0438\u0441\u043A\u0440\u0430. \u0418\u043D\u0442\u0435\u0440\u0435\u0441 \u0436\u0438\u0432\u043E\u0439: \u0447\u0435\u043B\u043E\u0432\u0435\u043A \u0437\u0430\u0433\u043E\u0440\u0435\u043B\u0441\u044F, \u043D\u043E \u0435\u0449\u0451 \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u043E\u0431\u0441\u0442\u0440\u043E\u0438\u043B.", "w": "\u0418\u0434\u0435\u044F \u043F\u0440\u043E\u0441\u0438\u0442 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F \u0441\u0435\u0433\u043E\u0434\u043D\u044F. \u0417\u0430\u043F\u0438\u0448\u0438\u0442\u0435 \u0438 \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u0435, \u043D\u0435 \u043A\u043B\u0430\u0434\u0438\u0442\u0435 \u0432 \u0441\u0442\u043E\u043B.", "m": "\u041D\u0430 \u0433\u043E\u0440\u0438\u0437\u043E\u043D\u0442\u0435 \u043D\u043E\u0432\u044B\u0439 \u0438\u0441\u0442\u043E\u0447\u043D\u0438\u043A. \u041F\u0440\u0438\u0441\u043C\u043E\u0442\u0440\u0438\u0442\u0435\u0441\u044C, \u043D\u0435 \u043E\u0442\u043C\u0430\u0445\u0438\u0432\u0430\u0439\u0442\u0435\u0441\u044C.", "a": "\u0421\u0434\u0435\u043B\u0430\u0439\u0442\u0435 \u043E\u0434\u0438\u043D \u043F\u0435\u0440\u0432\u044B\u0439 \u0448\u0430\u0433: \u0437\u0432\u043E\u043D\u043E\u043A, \u043F\u0438\u0441\u044C\u043C\u043E, \u043D\u0430\u0447\u0430\u043B\u043E." }, "wands_2": { "l": "\u0421\u0447\u0438\u0442\u0430\u044E\u0442, \u043A\u0430\u043A\u043E\u0439 \u0431\u0443\u0434\u0435\u0442 \u043C\u0430\u0441\u0448\u0442\u0430\u0431: \u0434\u0430\u043B\u044C\u0448\u0435 \u0432\u043C\u0435\u0441\u0442\u0435 \u0438\u043B\u0438 \u043F\u043E\u0440\u043E\u0437\u043D\u044C. \u042D\u0442\u043E \u043D\u0435 \u0432\u0441\u043F\u044B\u0448\u043A\u0430, \u0430 \u0440\u0430\u0437\u0432\u0438\u043B\u043A\u0430.", "w": "\u041F\u043B\u0430\u043D\u0438\u0440\u0443\u0439\u0442\u0435 \u0431\u043E\u043B\u044C\u0448\u043E\u0435. \u0412\u044B \u0443\u0436\u0435 \u043F\u0435\u0440\u0435\u0440\u043E\u0441\u043B\u0438 \u043F\u0440\u0438\u0432\u044B\u0447\u043D\u044B\u0435 \u0431\u0435\u0440\u0435\u0433\u0430.", "m": "\u041F\u043E\u0441\u0447\u0438\u0442\u0430\u0439\u0442\u0435, \u0432\u043E \u0447\u0442\u043E \u0432\u043B\u043E\u0436\u0438\u0442\u044C \u0441\u0438\u043B\u044B \u0438 \u0434\u0435\u043D\u044C\u0433\u0438, \u043F\u0440\u0435\u0436\u0434\u0435 \u0447\u0435\u043C \u0448\u0430\u0433\u0430\u0442\u044C.", "a": "\u0420\u0435\u0448\u0438\u0442\u0435 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0448\u0430\u0433 \u0438 \u043D\u0435 \u043E\u0442\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0439\u0442\u0435 \u0435\u0433\u043E." }, "wands_3": { "l": "\u0412\u0437\u0430\u0438\u043C\u043D\u043E\u0441\u0442\u044C \u0443\u0436\u0435 \u0432 \u043F\u0443\u0442\u0438. \u0427\u0435\u043B\u043E\u0432\u0435\u043A \u0441\u043C\u043E\u0442\u0440\u0438\u0442 \u0432\u043F\u0435\u0440\u0451\u0434, \u0436\u0434\u0430\u0442\u044C \u043E\u0441\u0442\u0430\u043B\u043E\u0441\u044C \u043D\u0435\u0434\u043E\u043B\u0433\u043E.", "w": "\u041F\u0435\u0440\u0432\u044B\u0435 \u043F\u043B\u043E\u0434\u044B \u0443\u0436\u0435 \u043F\u043B\u044B\u0432\u0443\u0442. \u0413\u043E\u0442\u043E\u0432\u044C\u0442\u0435 \u043C\u0435\u0441\u0442\u043E \u0434\u043B\u044F \u0440\u043E\u0441\u0442\u0430.", "m": "\u0412\u043B\u043E\u0436\u0435\u043D\u043D\u043E\u0435 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0442\u044C\u0441\u044F. \u041D\u0435 \u0434\u0451\u0440\u0433\u0430\u0439\u0442\u0435 \u0440\u0430\u043D\u044C\u0448\u0435 \u0432\u0440\u0435\u043C\u0435\u043D\u0438.", "a": "\u0414\u0435\u0440\u0436\u0438\u0442\u0435 \u043A\u0443\u0440\u0441 \u0438 \u0441\u043C\u043E\u0442\u0440\u0438\u0442\u0435 \u0432\u0434\u0430\u043B\u044C." }, "wands_4": { "l": "\u041C\u0435\u0436\u0434\u0443 \u0432\u0430\u043C\u0438 \u043C\u0435\u0441\u0442\u043E \u0434\u043B\u044F \u043F\u0440\u0430\u0437\u0434\u043D\u0438\u043A\u0430: \u0432\u0441\u0442\u0440\u0435\u0447\u0430, \u0434\u043E\u043C, \xAB\u043C\u044B\xBB. \u042D\u0442\u043E \u0440\u0430\u0434\u043E\u0441\u0442\u044C, \u043D\u0435 \u0438\u0441\u043F\u044B\u0442\u0430\u043D\u0438\u0435.", "w": "\u042D\u0442\u0430\u043F \u0437\u0430\u043A\u0440\u044B\u0442 \u043A\u0440\u0430\u0441\u0438\u0432\u043E. \u041E\u0442\u043C\u0435\u0442\u044C\u0442\u0435 \u0441 \u043A\u043E\u043C\u0430\u043D\u0434\u043E\u0439, \u0432\u044B \u044D\u0442\u043E \u0437\u0430\u0441\u043B\u0443\u0436\u0438\u043B\u0438.", "m": "\u0414\u043E\u0441\u0442\u0430\u0442\u043A\u0430 \u0445\u0432\u0430\u0442\u0430\u0435\u0442, \u0447\u0442\u043E\u0431\u044B \u043F\u043E\u0434\u0435\u043B\u0438\u0442\u044C\u0441\u044F. \u041D\u0435 \u0436\u0430\u0434\u043D\u0438\u0447\u0430\u0439\u0442\u0435 \u0441\u0435\u0433\u043E\u0434\u043D\u044F.", "a": "\u0423\u0441\u0442\u0440\u043E\u0439\u0442\u0435 \u0441\u0435\u0431\u0435 \u043C\u0430\u043B\u0435\u043D\u044C\u043A\u0438\u0439 \u043F\u0440\u0430\u0437\u0434\u043D\u0438\u043A." }, "wands_5": { "l": "\u041C\u0435\u0436\u0434\u0443 \u0432\u0430\u043C\u0438 \u0441\u043F\u043E\u0440 \u0438 \u043F\u0440\u0438\u0442\u0438\u0440\u043A\u0430, \u043D\u0435 \u0432\u043E\u0439\u043D\u0430. \u0410\u0437\u0430\u0440\u0442 \u0435\u0441\u0442\u044C, \u0436\u0435\u043B\u0430\u043D\u0438\u044F \u0432\u0430\u0441 \u0443\u043D\u0438\u0447\u0442\u043E\u0436\u0438\u0442\u044C \u043D\u0435\u0442.", "w": "\u041A\u043E\u043D\u043A\u0443\u0440\u0435\u043D\u0446\u0438\u044F \u0441\u0435\u0439\u0447\u0430\u0441 \u043A\u0430\u043A \u0442\u0440\u0435\u043D\u0438\u0440\u043E\u0432\u043A\u0430, \u043D\u0435 \u043A\u0430\u043A \u0443\u0433\u0440\u043E\u0437\u0430. \u041D\u0435 \u043F\u0440\u0438\u043D\u0438\u043C\u0430\u0439\u0442\u0435 \u0431\u043B\u0438\u0437\u043A\u043E \u043A \u0441\u0435\u0440\u0434\u0446\u0443.", "m": "\u0421\u043F\u043E\u0440\u044F\u0442 \u043E \u0441\u0443\u043C\u043C\u0430\u0445. \u0414\u0435\u0440\u0436\u0438\u0442\u0435\u0441\u044C \u0441\u043F\u043E\u043A\u043E\u0439\u043D\u043E, \u0441 \u044E\u043C\u043E\u0440\u043E\u043C.", "a": "\u041D\u0435 \u0442\u0440\u0430\u0442\u044C\u0442\u0435 \u0441\u0438\u043B\u044B \u043D\u0430 \u0441\u043F\u043E\u0440. \u041D\u0430\u043F\u0440\u0430\u0432\u044C\u0442\u0435 \u0438\u0445 \u0432 \u0434\u0435\u043B\u043E." }, "wands_6": { "l": "\u0412\u0430\u043C\u0438 \u0432\u043E\u0441\u0445\u0438\u0449\u0430\u044E\u0442\u0441\u044F. \u042D\u0442\u043E \u043F\u0440\u0438\u0437\u043D\u0430\u043D\u0438\u0435, \u043D\u0435 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u043D\u0430 \u0432\u0441\u044E \u0436\u0438\u0437\u043D\u044C.", "w": "\u0412\u0430\u0441 \u043F\u043E\u0445\u0432\u0430\u043B\u044F\u0442. \u041F\u0440\u0438\u043C\u0438\u0442\u0435 \u044D\u0442\u043E, \u0432\u044B \u0448\u043B\u0438 \u0434\u043E\u043B\u044C\u0448\u0435, \u0447\u0435\u043C \u043A\u0430\u0436\u0435\u0442\u0441\u044F.", "m": "\u0412\u043E\u0437\u043C\u043E\u0436\u043D\u044B \u0443\u0434\u0430\u0447\u043D\u0430\u044F \u0441\u0434\u0435\u043B\u043A\u0430 \u0438\u043B\u0438 \u043F\u043E\u0432\u044B\u0448\u0435\u043D\u0438\u0435. \u041D\u0435 \u043F\u0440\u044F\u0447\u044C\u0442\u0435\u0441\u044C.", "a": "\u041F\u043E\u0434\u043D\u0438\u043C\u0438\u0442\u0435 \u0433\u043E\u043B\u043E\u0432\u0443 \u0438 \u043F\u0440\u0438\u043C\u0438\u0442\u0435 \u043F\u043E\u0431\u0435\u0434\u0443. \u041E\u043D\u0430 \u0432\u0430\u0448\u0430." }, "wands_7": { "l": "\u0427\u0435\u043B\u043E\u0432\u0435\u043A \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u0441\u0432\u043E\u0451. \u0415\u0441\u043B\u0438 \u0441\u043E\u044E\u0437 \u0434\u043E\u0440\u043E\u0433 \u2014 \u0431\u0443\u0434\u0435\u0442 \u0441\u0442\u043E\u044F\u0442\u044C. \u0415\u0441\u043B\u0438 \u043D\u0435\u0442 \u2014 \u043E\u0442\u043E\u0434\u0432\u0438\u043D\u0435\u0442 \u0432\u0430\u0441.", "w": "\u041F\u043E\u0437\u0438\u0446\u0438\u044F \u0432\u044B\u0448\u0435, \u0447\u0435\u043C \u043A\u0430\u0436\u0435\u0442\u0441\u044F. \u0421\u0442\u043E\u0439\u0442\u0435, \u043D\u0435 \u043E\u0442\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u043C\u0435\u0441\u0442\u043E.", "m": "\u0417\u0430\u0449\u0438\u0442\u0438\u0442\u0435 \u0441\u0432\u043E\u0451: \u043F\u0435\u0440\u0435\u0441\u043C\u043E\u0442\u0440\u0438\u0442\u0435 \u0443\u0441\u043B\u043E\u0432\u0438\u044F, \u043F\u043E\u0442\u043E\u0440\u0433\u0443\u0439\u0442\u0435\u0441\u044C.", "a": "\u0421\u0442\u043E\u0439\u0442\u0435 \u043D\u0430 \u0441\u0432\u043E\u0451\u043C \u0441\u043F\u043E\u043A\u043E\u0439\u043D\u043E. \u0412\u044B\u0441\u043E\u0442\u0430 \u0437\u0430 \u0432\u0430\u043C\u0438." }, "wands_8": { "l": "\u0412\u0441\u0451 \u0443\u0441\u043A\u043E\u0440\u044F\u0435\u0442\u0441\u044F: \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u044F, \u0448\u0430\u0433\u0438, \u0440\u0435\u0448\u0435\u043D\u0438\u044F. \u0422\u044F\u043D\u0443\u0442\u044C \u044D\u0442\u043E\u0442 \u0447\u0435\u043B\u043E\u0432\u0435\u043A \u043D\u0435 \u0431\u0443\u0434\u0435\u0442.", "w": "\u041D\u043E\u0432\u043E\u0441\u0442\u0438 \u0438 \u0441\u0440\u043E\u043A\u0438 \u043D\u0435\u0441\u0443\u0442\u0441\u044F. \u041D\u0435 \u0442\u043E\u0440\u043C\u043E\u0437\u0438\u0442\u0435, \u043F\u043E\u043A\u0430 \u0432\u0435\u0442\u0435\u0440 \u043F\u043E\u043F\u0443\u0442\u043D\u044B\u0439.", "m": "\u0414\u0435\u043D\u044C\u0433\u0438 \u043C\u043E\u0433\u0443\u0442 \u043F\u0440\u0438\u0439\u0442\u0438 \u0431\u044B\u0441\u0442\u0440\u043E \u0438 \u0443\u0439\u0442\u0438 \u0431\u044B\u0441\u0442\u0440\u043E. \u0411\u0443\u0434\u044C\u0442\u0435 \u0432\u043D\u0438\u043C\u0430\u0442\u0435\u043B\u044C\u043D\u044B.", "a": "\u0414\u0435\u0439\u0441\u0442\u0432\u0443\u0439\u0442\u0435 \u0431\u044B\u0441\u0442\u0440\u043E, \u043F\u043E\u043A\u0430 \u0445\u043E\u0434 \u043E\u0442\u043A\u0440\u044B\u0442." }, "wands_9": { "l": "\u0427\u0435\u043B\u043E\u0432\u0435\u043A \u0443\u0441\u0442\u0430\u043B \u0438 \u0434\u0435\u0440\u0436\u0438\u0442 \u0449\u0438\u0442. \u0421\u0442\u0430\u0440\u044B\u0435 \u0440\u0430\u043D\u044B \u043C\u043E\u0433\u0443\u0442 \u0437\u0430\u043A\u0440\u044B\u0432\u0430\u0442\u044C \u0432\u0430\u0441. \u042D\u0442\u043E \u043E\u0441\u0442\u043E\u0440\u043E\u0436\u043D\u043E\u0441\u0442\u044C, \u043D\u0435 \u0440\u0430\u0432\u043D\u043E\u0434\u0443\u0448\u0438\u0435.", "w": "\u041F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u0431\u0430\u0440\u044C\u0435\u0440. \u0412\u044B \u0431\u043B\u0438\u0436\u0435 \u043A \u0446\u0435\u043B\u0438, \u0447\u0435\u043C \u0434\u0443\u043C\u0430\u0435\u0442\u0435, \u043D\u0435 \u0431\u0440\u043E\u0441\u0430\u0439\u0442\u0435 \u043D\u0430 \u0444\u0438\u043D\u0438\u0448\u0435.", "m": "\u041F\u043E\u0441\u043B\u0435 \u043F\u043E\u0442\u0435\u0440\u044C \u043E\u0441\u0442\u043E\u0440\u043E\u0436\u043D\u043E\u0441\u0442\u044C \u043D\u043E\u0440\u043C\u0430\u043B\u044C\u043D\u0430. \u0422\u043E\u043B\u044C\u043A\u043E \u043D\u0435 \u043C\u0435\u0448\u0430\u0439\u0442\u0435 \u0441\u0435\u0431\u0435 \u0436\u0438\u0442\u044C.", "a": "\u0421\u043E\u0431\u0435\u0440\u0438\u0442\u0435\u0441\u044C \u043D\u0430 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u0440\u044B\u0432\u043E\u043A. \u041E\u043D \u0438 \u043F\u0440\u0430\u0432\u0434\u0430 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439." }, "wands_10": { "l": "\u041D\u043E\u0448\u0443 \u0442\u0430\u0449\u0438\u0442 \u043E\u0434\u0438\u043D. \u041B\u0438\u0431\u043E \u0436\u0434\u0443\u0442, \u0447\u0442\u043E \u043F\u043E\u0442\u0430\u0449\u0438\u0442\u0435 \u0432\u044B, \u043B\u0438\u0431\u043E \u0441\u0430\u043C\u0438 \u0443\u0436\u0435 \u043D\u0430\u0434\u043E\u0440\u0432\u0430\u043B\u0438\u0441\u044C.", "w": "\u041F\u0435\u0440\u0435\u0433\u0440\u0443\u0437. \u041E\u0442\u0434\u0430\u0439\u0442\u0435 \u0447\u0430\u0441\u0442\u044C, \u0438\u043D\u0430\u0447\u0435 \u0434\u043E\u0439\u0434\u0451\u0442\u0435 \u0431\u0435\u0437 \u0441\u0438\u043B.", "m": "\u0421\u043B\u0438\u0448\u043A\u043E\u043C \u043C\u043D\u043E\u0433\u043E \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u0441\u0442\u0432. \u0421\u043E\u043A\u0440\u0430\u0449\u0430\u0439\u0442\u0435, \u043D\u0435 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0439\u0442\u0435.", "a": "\u041E\u0442\u043B\u043E\u0436\u0438\u0442\u0435 \u043F\u043E\u043B\u043E\u0432\u0438\u043D\u0443 \u043D\u043E\u0448\u0438. \u041E\u043D\u0430 \u043D\u0435 \u0432\u0430\u0448\u0430." }, "wands_page": { "l": "\u0415\u0441\u0442\u044C \u0444\u043B\u0438\u0440\u0442 \u0438 \u0432\u0435\u0441\u0442\u043E\u0447\u043A\u0438. \u0418\u043D\u0442\u0435\u0440\u0435\u0441 \u043B\u0451\u0433\u043A\u0438\u0439, \u0434\u043E \u0432\u0437\u0440\u043E\u0441\u043B\u043E\u0433\u043E \u0441\u043E\u044E\u0437\u0430 \u0435\u0449\u0451 \u0434\u0430\u043B\u0435\u043A\u043E.", "w": "\u041D\u043E\u0432\u044B\u0435 \u0438\u0434\u0435\u0438 \u0438 \u0443\u0447\u0451\u0431\u0430. \u041F\u0440\u043E\u0431\u0443\u0439\u0442\u0435, \u043A\u0430\u043A \u0432 \u0438\u0433\u0440\u0435, \u0431\u0435\u0437 \u0441\u0442\u0440\u0430\u0445\u0430 \u043E\u0448\u0438\u0431\u043A\u0438.", "m": "\u041C\u0430\u043B\u0435\u043D\u044C\u043A\u0438\u0439 \u0434\u043E\u0445\u043E\u0434, \u043D\u043E \u043E\u0431\u043D\u0430\u0434\u0451\u0436\u0438\u0432\u0430\u044E\u0449\u0438\u0439. \u041D\u0435 \u043F\u0440\u0435\u0437\u0438\u0440\u0430\u0439\u0442\u0435 \u0435\u0433\u043E.", "a": "\u041F\u043E\u0434\u043E\u0439\u0434\u0438\u0442\u0435 \u043A \u043D\u043E\u0432\u043E\u043C\u0443 \u0441 \u043B\u044E\u0431\u043E\u043F\u044B\u0442\u0441\u0442\u0432\u043E\u043C." }, "wands_knight": { "l": "\u0421\u0442\u0440\u0430\u0441\u0442\u043D\u044B\u0439 \u043F\u043E\u0440\u044B\u0432: \u0447\u0435\u043B\u043E\u0432\u0435\u043A \u0441\u043A\u0430\u0447\u0435\u0442 \u0432\u043F\u0435\u0440\u0451\u0434. \u042D\u0442\u043E \u0436\u0430\u0440\u0430, \u043D\u0435 \u0431\u044B\u0442.", "w": "\u0421\u0438\u043B \u043C\u043D\u043E\u0433\u043E. \u0411\u0435\u0440\u0438\u0442\u0435\u0441\u044C \u0437\u0430 \u0441\u043C\u0435\u043B\u044B\u0439 \u043F\u0440\u043E\u0435\u043A\u0442, \u0442\u043E\u043B\u044C\u043A\u043E \u043D\u0435 \u0440\u0430\u0441\u043F\u044B\u043B\u044F\u0439\u0442\u0435\u0441\u044C.", "m": "\u0425\u043E\u0434 \u0431\u044B\u0441\u0442\u0440\u044B\u0439 \u0438 \u0440\u0438\u0441\u043A\u043E\u0432\u0430\u043D\u043D\u044B\u0439. \u0412\u0437\u0432\u0435\u0441\u044C\u0442\u0435 \u0434\u0432\u0430\u0436\u0434\u044B, \u043F\u043E\u0442\u043E\u043C \u0441\u043A\u0430\u0447\u0438\u0442\u0435.", "a": "\u0418\u0434\u0438\u0442\u0435 \u0432\u043F\u0435\u0440\u0451\u0434, \u043D\u043E \u0434\u0435\u0440\u0436\u0438\u0442\u0435 \u043F\u043E\u0432\u043E\u0434\u044C\u044F." }, "wands_queen": { "l": "\u0427\u0435\u043B\u043E\u0432\u0435\u043A \u0441\u0432\u0435\u0442\u0438\u0442 \u0442\u0435\u043F\u043B\u043E\u043C \u0438 \u0443\u0432\u0435\u0440\u0435\u043D\u043D\u043E\u0441\u0442\u044C\u044E. \u041A \u043D\u0435\u043C\u0443 \u0442\u044F\u043D\u0443\u0442\u0441\u044F. \u0421\u043C\u043E\u0442\u0440\u0438\u0442\u0435, \u0437\u043E\u0432\u0443\u0442 \u043B\u0438 \u0432\u0430\u0441 \u0432 \u044D\u0442\u043E\u0442 \u0441\u0432\u0435\u0442.", "w": "\u0422\u0435\u043F\u043B\u043E \u0438 \u0441\u043E\u0431\u0440\u0430\u043D\u043D\u043E\u0441\u0442\u044C \u043F\u0440\u0438\u0432\u043E\u0434\u044F\u0442 \u043B\u044E\u0434\u0435\u0439 \u043A \u0432\u0430\u0448\u0435\u043C\u0443 \u0441\u0442\u043E\u043B\u0443. \u042D\u0442\u043E \u043F\u0440\u043E \u0434\u0435\u043B\u043E, \u043D\u0435 \u043F\u0440\u043E \u0440\u043E\u043C\u0430\u043D.", "m": "\u0414\u0435\u043D\u044C\u0433\u0438 \u043C\u043E\u0433\u0443\u0442 \u043F\u0440\u0438\u0439\u0442\u0438 \u0447\u0435\u0440\u0435\u0437 \u0434\u043E\u0432\u0435\u0440\u0438\u0435 \u043A \u0432\u0430\u043C. \u0421\u0443\u043C\u043C\u0443 \u0432\u0441\u0451 \u0440\u0430\u0432\u043D\u043E \u0441\u0447\u0438\u0442\u0430\u0439\u0442\u0435.", "a": "\u0421\u043C\u043E\u0442\u0440\u0438\u0442\u0435, \u0433\u0434\u0435 \u043A \u0432\u0430\u043C \u0443\u0436\u0435 \u0442\u044F\u043D\u0443\u0442\u0441\u044F. \u041D\u0430\u0437\u043B\u043E \u0432\u043E\u043F\u0440\u043E\u0441\u0443 \u0441\u0432\u0435\u0442\u0438\u0442\u044C \u043D\u0435 \u043D\u0443\u0436\u043D\u043E." }, "wands_king": { "l": "\u042D\u0442\u043E\u0442 \u0447\u0435\u043B\u043E\u0432\u0435\u043A \u0445\u043E\u0447\u0435\u0442 \u0432\u0435\u0441\u0442\u0438. \u0421\u0442\u0440\u0430\u0441\u0442\u044C \u0437\u0440\u0435\u043B\u0430\u044F, \u0441\u043E \u0441\u0432\u043E\u0438\u043C \u043A\u0443\u0440\u0441\u043E\u043C. \u0427\u0442\u043E\u0431\u044B \u0438\u043C \u0432\u0435\u0440\u0442\u0435\u043B\u0438, \u043D\u0435 \u043F\u0440\u043E\u0441\u0438\u0442.", "w": "\u041D\u0443\u0436\u0435\u043D \u0442\u043E\u0442, \u043A\u0442\u043E \u0437\u0430\u0434\u0430\u0451\u0442 \u043A\u0443\u0440\u0441. \u041D\u0435 \u0445\u0432\u0430\u0442\u0430\u0439\u0442\u0435 \u0447\u0443\u0436\u043E\u0435 \u043C\u0435\u0441\u0442\u043E: \u043B\u0438\u0431\u043E \u0432\u0430\u043C \u0435\u0433\u043E \u043E\u0442\u0434\u0430\u044E\u0442, \u043B\u0438\u0431\u043E \u0436\u0434\u0438\u0442\u0435 \u044F\u0441\u043D\u043E\u0433\u043E \u0440\u0443\u043A\u043E\u0432\u043E\u0434\u0438\u0442\u0435\u043B\u044F.", "m": "\u0414\u0443\u043C\u0430\u0439\u0442\u0435 \u0448\u0438\u0440\u0435 \u043E\u0434\u043D\u043E\u0439 \u043D\u0435\u0434\u0435\u043B\u0438. \u042D\u0442\u043E \u043F\u0440\u043E \u0440\u043E\u0441\u0442, \u043D\u0435 \u043F\u0440\u043E \u0442\u043E, \u0447\u0442\u043E \u0441\u0443\u043C\u043C\u0430 \u0443\u0436\u0435 \u0432 \u043A\u0430\u0440\u043C\u0430\u043D\u0435.", "a": "\u041D\u0430\u0437\u043E\u0432\u0438\u0442\u0435, \u043A\u0442\u043E \u0437\u0434\u0435\u0441\u044C \u0432\u0435\u0434\u0451\u0442. \u0427\u0443\u0436\u043E\u0435 \u043C\u0435\u0441\u0442\u043E \u0438\u0437 \u0432\u0435\u0436\u043B\u0438\u0432\u043E\u0441\u0442\u0438 \u043D\u0435 \u0431\u0435\u0440\u0438\u0442\u0435." }, "swords_ace": { "l": "\u0427\u0435\u043B\u043E\u0432\u0435\u043A \u0432\u0438\u0434\u0438\u0442 \u044F\u0441\u043D\u043E \u0438 \u043C\u043E\u0436\u0435\u0442 \u0441\u043A\u0430\u0437\u0430\u0442\u044C \u043F\u0440\u0430\u0432\u0434\u0443 \u0432 \u043B\u043E\u0431. \u041D\u0435\u0436\u043D\u043E\u0441\u0442\u0438 \u0432 \u044D\u0442\u043E\u043C \u0441\u043B\u043E\u0432\u0435 \u043C\u0430\u043B\u043E.", "w": "\u0420\u0435\u0448\u0435\u043D\u0438\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u043E. \u0417\u0430\u0444\u0438\u043A\u0441\u0438\u0440\u0443\u0439\u0442\u0435 \u0435\u0433\u043E, \u043F\u043E\u043A\u0430 \u0442\u0443\u043C\u0430\u043D \u043D\u0435 \u0432\u0435\u0440\u043D\u0443\u043B\u0441\u044F.", "m": "\u0426\u0438\u0444\u0440\u044B \u0441\u0435\u0433\u043E\u0434\u043D\u044F \u043D\u0430 \u0432\u0430\u0448\u0435\u0439 \u0441\u0442\u043E\u0440\u043E\u043D\u0435. \u0421\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u043F\u0440\u044F\u043C\u043E.", "a": "\u0421\u043A\u0430\u0436\u0438\u0442\u0435 \u043E\u0434\u043D\u043E \u044F\u0441\u043D\u043E\u0435. \u041B\u0438\u0448\u043D\u0435\u0433\u043E \u043D\u0435 \u0434\u043E\u0433\u043E\u0432\u0430\u0440\u0438\u0432\u0430\u0439\u0442\u0435." }, "swords_2": { "l": "\u0412\u044B\u0431\u043E\u0440 \u0437\u0430\u043C\u043E\u0440\u043E\u0436\u0435\u043D. \u041E\u0431\u0430 \u043F\u0443\u0442\u0438 \u0435\u0449\u0451 \u0434\u043E\u0440\u043E\u0433\u0438, \u043F\u043E\u0432\u044F\u0437\u043A\u0443 \u0441 \u0433\u043B\u0430\u0437 \u043D\u0435 \u0441\u043D\u0438\u043C\u0430\u044E\u0442.", "w": "\u0414\u0432\u0430 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0430. \u0421\u043E\u0431\u0435\u0440\u0438\u0442\u0435 \u0444\u0430\u043A\u0442\u044B, \u043D\u0435 \u043C\u043D\u0435\u043D\u0438\u044F.", "m": "\u0412\u044B\u0431\u043E\u0440 \u043C\u0435\u0436\u0434\u0443 \u0434\u0432\u0443\u043C\u044F \u0442\u0440\u0430\u0442\u0430\u043C\u0438. \u0421\u0447\u0438\u0442\u0430\u0439\u0442\u0435, \u043D\u0435 \u0433\u0430\u0434\u0430\u0439\u0442\u0435.", "a": "\u0421\u043D\u0438\u043C\u0438\u0442\u0435 \u043F\u043E\u0432\u044F\u0437\u043A\u0443. \u0412\u044B \u0432\u0441\u0451 \u0443\u0436\u0435 \u0437\u043D\u0430\u0435\u0442\u0435." }, "swords_3": { "l": "\u0421\u0435\u0440\u0434\u0446\u0435 \u0437\u0430\u0434\u0435\u0442\u043E, \u0431\u043E\u043B\u044C \u043D\u0430\u0441\u0442\u043E\u044F\u0449\u0430\u044F. \u041C\u043E\u043B\u0447\u0430\u043D\u0438\u0435 \u043D\u0435 \u0437\u043D\u0430\u0447\u0438\u0442, \u0447\u0442\u043E \u0432\u0441\u0451 \u043F\u0440\u043E\u0448\u043B\u043E.", "w": "\u041F\u0440\u0438\u0448\u043B\u0430 \u043D\u0435\u043F\u0440\u0438\u044F\u0442\u043D\u0430\u044F \u043D\u043E\u0432\u043E\u0441\u0442\u044C. \u041F\u0440\u0438\u043C\u0438\u0442\u0435 \u0435\u0451 \u0438 \u043F\u0435\u0440\u0435\u0441\u0442\u0440\u043E\u0439\u0442\u0435 \u043F\u043B\u0430\u043D.", "m": "\u041F\u043E\u0442\u0435\u0440\u044F \u0438\u043B\u0438 \u0440\u0430\u0437\u043E\u0447\u0430\u0440\u043E\u0432\u0430\u043D\u0438\u0435. \u0423\u0440\u043E\u043A \u0434\u043E\u0440\u043E\u0436\u0435 \u0441\u0443\u043C\u043C\u044B.", "a": "\u0414\u0430\u0439\u0442\u0435 \u0441\u0435\u0431\u0435 \u043F\u0440\u043E\u0436\u0438\u0442\u044C \u043E\u0431\u0438\u0434\u0443 \u0438 \u043E\u0442\u043F\u0443\u0441\u0442\u0438\u0442\u0435." }, "swords_4": { "l": "\u041D\u0443\u0436\u043D\u0430 \u043F\u0430\u0443\u0437\u0430. \u0427\u0435\u043B\u043E\u0432\u0435\u043A \u043E\u0442\u0445\u043E\u0434\u0438\u0442 \u043E\u0442\u0434\u043E\u0445\u043D\u0443\u0442\u044C, \u043D\u0435 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E \u0443\u0445\u043E\u0434\u0438\u0442 \u043D\u0430\u0432\u0441\u0435\u0433\u0434\u0430.", "w": "\u0422\u0438\u0445\u0438\u0439 \u0434\u0435\u043D\u044C \u0438\u043B\u0438 \u043E\u0442\u043F\u0443\u0441\u043A \u0432\u0430\u0436\u043D\u0435\u0435 \u0440\u044B\u0432\u043A\u0430. \u0421\u0438\u043B\u044B \u043A\u043E\u043D\u0447\u0438\u043B\u0438\u0441\u044C.", "m": "\u0417\u0430\u043C\u043E\u0440\u043E\u0437\u044C\u0442\u0435 \u0434\u0435\u043D\u0435\u0436\u043D\u044B\u0435 \u0440\u0435\u0448\u0435\u043D\u0438\u044F \u0434\u043E \u043B\u0443\u0447\u0448\u0438\u0445 \u0432\u0440\u0435\u043C\u0451\u043D.", "a": "\u041B\u043E\u0436\u0438\u0442\u0435\u0441\u044C \u0441\u043F\u0430\u0442\u044C \u0440\u0430\u043D\u044C\u0448\u0435. \u042D\u0442\u043E \u0441\u0435\u0439\u0447\u0430\u0441 \u043B\u0443\u0447\u0448\u0438\u0439 \u0445\u043E\u0434." }, "swords_5": { "l": "\u0412 \u0441\u043F\u043E\u0440\u0435 \u043F\u043E\u0431\u0435\u0434\u0430 \u0432\u0430\u0436\u043D\u0435\u0435 \u0442\u0435\u043F\u043B\u0430. \u041C\u043E\u0433\u0443\u0442 \u0432\u044B\u0438\u0433\u0440\u0430\u0442\u044C \u0438 \u043E\u0441\u0442\u0430\u0442\u044C\u0441\u044F \u043D\u0438 \u0441 \u0447\u0435\u043C.", "w": "\u041A\u043E\u043D\u0444\u043B\u0438\u043A\u0442: \u0432\u044B\u0438\u0433\u0440\u0430\u0442\u044C \u043C\u043E\u0436\u043D\u043E, \u0430 \u043D\u0443\u0436\u043D\u043E \u043B\u0438 \u2014 \u0434\u0440\u0443\u0433\u043E\u0439 \u0440\u0430\u0437\u0433\u043E\u0432\u043E\u0440. \u041B\u0443\u0447\u0448\u0435 \u043C\u0438\u0440.", "m": "\u0412\u044B\u0433\u043E\u0434\u0430 \u0441 \u043D\u0435\u043F\u0440\u0438\u044F\u0442\u043D\u044B\u043C \u043F\u0440\u0438\u0432\u043A\u0443\u0441\u043E\u043C. \u041F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u0446\u0435\u043D\u0443.", "a": "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043C\u0438\u0440, \u0430 \u043D\u0435 \u043F\u043E\u0431\u0435\u0434\u0443." }, "swords_6": { "l": "\u0427\u0435\u043B\u043E\u0432\u0435\u043A \u0442\u0438\u0445\u043E \u0443\u0445\u043E\u0434\u0438\u0442 \u043E\u0442 \u0431\u043E\u043B\u0438 \u043A \u0441\u043F\u043E\u043A\u043E\u0439\u043D\u043E\u043C\u0443. \u0412\u043E\u0435\u0432\u0430\u0442\u044C \u0441 \u0432\u0430\u043C\u0438 \u043D\u0435 \u0445\u043E\u0447\u0435\u0442.", "w": "\u041F\u0435\u0440\u0435\u0445\u043E\u0434: \u043D\u043E\u0432\u043E\u0435 \u043C\u0435\u0441\u0442\u043E \u0438\u043B\u0438 \u0440\u043E\u043B\u044C \u0431\u0443\u0434\u0443\u0442 \u0441\u043F\u043E\u043A\u043E\u0439\u043D\u0435\u0435. \u042D\u0442\u043E \u043D\u0435 \u0431\u0435\u0433\u0441\u0442\u0432\u043E.", "m": "\u0412\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0434\u0435\u043D\u0435\u0433 \u043F\u043E\u0439\u0434\u0451\u0442 \u043F\u043E\u0441\u0442\u0435\u043F\u0435\u043D\u043D\u043E. \u041D\u0435 \u0436\u0434\u0438\u0442\u0435 \u0447\u0443\u0434\u0430 \u0437\u0430 \u043D\u043E\u0447\u044C.", "a": "\u041F\u043B\u044B\u0432\u0438\u0442\u0435 \u043A \u0441\u043F\u043E\u043A\u043E\u0439\u043D\u043E\u043C\u0443 \u0431\u0435\u0440\u0435\u0433\u0443. \u041D\u0435 \u043E\u0433\u043B\u044F\u0434\u044B\u0432\u0430\u0439\u0442\u0435\u0441\u044C." }, "swords_7": { "l": "\u041D\u0435 \u0432\u0441\u0451 \u0441\u043A\u0430\u0437\u0430\u043D\u043E. \u0414\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0442 \u0432 \u043E\u0431\u0445\u043E\u0434. \u041A\u0440\u0430\u0441\u0438\u0432\u043E\u043C\u0443 \u0445\u043E\u0434\u0443 \u043B\u0443\u0447\u0448\u0435 \u043D\u0435 \u0432\u0435\u0440\u0438\u0442\u044C \u0441\u0440\u0430\u0437\u0443.", "w": "\u041F\u0440\u044F\u043C\u043E\u0439 \u043F\u0443\u0442\u044C \u043D\u0435 \u0435\u0434\u0438\u043D\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439. \u0418\u0449\u0438\u0442\u0435 \u0443\u043C\u043D\u044B\u0439 \u0445\u043E\u0434, \u043D\u0435 \u0447\u0443\u0436\u043E\u0435.", "m": "\u041F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435, \u0433\u0434\u0435 \u0442\u0438\u0445\u043E \u0443\u0442\u0435\u043A\u0430\u0435\u0442: \u043F\u043E\u0434\u043F\u0438\u0441\u043A\u0438, \u043A\u043E\u043C\u0438\u0441\u0441\u0438\u0438.", "a": "\u041F\u0440\u0438\u0434\u0443\u043C\u0430\u0439\u0442\u0435 \u0445\u0438\u0442\u0440\u044B\u0439, \u043D\u043E \u0447\u0435\u0441\u0442\u043D\u044B\u0439 \u043F\u0443\u0442\u044C." }, "swords_8": { "l": "\u0427\u0435\u043B\u043E\u0432\u0435\u043A\u0443 \u043A\u0430\u0436\u0435\u0442\u0441\u044F, \u0447\u0442\u043E \u043E\u043D \u0432 \u043B\u043E\u0432\u0443\u0448\u043A\u0435. \u0427\u0430\u0441\u0442\u043E \u044D\u0442\u043E \u0441\u0442\u0440\u0430\u0445, \u0430 \u043D\u0435 \u0432\u0430\u0448\u0438 \u043F\u0443\u0442\u044B \u043D\u0430 \u043D\u0451\u043C.", "w": "\u041A\u0430\u0436\u0435\u0442\u0441\u044F, \u0447\u0442\u043E \u0431\u0435\u0437 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u043E\u0432. \u041E\u043D\u0438 \u0435\u0441\u0442\u044C. \u0421\u043F\u0440\u043E\u0441\u0438\u0442\u0435 \u0441\u043E\u0432\u0435\u0442\u0430.", "m": "\u041E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u044F \u0432\u0440\u0435\u043C\u0435\u043D\u043D\u044B\u0435 \u0438 \u0447\u0430\u0441\u0442\u044C\u044E \u043C\u043D\u0438\u043C\u044B\u0435. \u041E\u0434\u0438\u043D \u0448\u0430\u0433 \u0432 \u0441\u0442\u043E\u0440\u043E\u043D\u0443 \u0443\u0436\u0435 \u0432\u044B\u0445\u043E\u0434.", "a": "\u0420\u0430\u0437\u0432\u044F\u0436\u0438\u0442\u0435 \u043E\u0434\u0438\u043D \u0443\u0437\u0435\u043B. \u041E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u043E\u0441\u043B\u0430\u0431\u043D\u0443\u0442 \u0441\u0430\u043C\u0438." }, "swords_9": { "l": "\u041D\u043E\u0447\u044C\u044E \u0442\u0440\u0435\u0432\u043E\u0433\u0430 \u0433\u0440\u043E\u043C\u0447\u0435 \u0447\u0443\u0432\u0441\u0442\u0432\u0430 \u043A \u0432\u0430\u043C. \u0414\u043D\u0451\u043C \u043C\u043E\u0436\u0435\u0442 \u043E\u043A\u0430\u0437\u0430\u0442\u044C\u0441\u044F, \u0447\u0442\u043E \u0441\u0442\u0440\u0430\u0445\u0438 \u043F\u0443\u0441\u0442\u044B\u0435.", "w": "\u0414\u0435\u0434\u043B\u0430\u0439\u043D \u043D\u043E\u0447\u044C\u044E \u043A\u0430\u0436\u0435\u0442\u0441\u044F \u043A\u0430\u0442\u0430\u0441\u0442\u0440\u043E\u0444\u043E\u0439. \u041F\u0440\u0438 \u0441\u0432\u0435\u0442\u0435 \u043E\u043D \u043C\u0435\u043D\u044C\u0448\u0435.", "m": "\u0421\u0442\u0440\u0430\u0445\u0438 \u0441\u0438\u043B\u044C\u043D\u0435\u0435 \u0446\u0438\u0444\u0440. \u041F\u043E\u0441\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u0441\u043F\u043E\u043A\u043E\u0439\u043D\u043E \u0443\u0442\u0440\u043E\u043C.", "a": "\u0417\u0430\u043F\u0438\u0448\u0438\u0442\u0435 \u0442\u0440\u0435\u0432\u043E\u0433\u0438 \u0438 \u043F\u0435\u0440\u0435\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u0434\u043D\u0451\u043C." }, "swords_10": { "l": "\u0425\u0443\u0434\u0448\u0435\u0435 \u043C\u0435\u0436\u0434\u0443 \u0432\u0430\u043C\u0438 \u0443\u0436\u0435 \u0431\u044B\u043B\u043E. \u0414\u0430\u043B\u044C\u0448\u0435 \u043B\u0438\u0431\u043E \u043F\u043E\u0434\u044A\u0451\u043C, \u043B\u0438\u0431\u043E \u043F\u0443\u0441\u0442\u043E\u0435 \u043F\u043E\u043B\u0435. \u041D\u0438\u0436\u0435 \u043D\u0435\u043A\u0443\u0434\u0430.", "w": "\u0414\u043D\u043E \u043F\u0440\u043E\u0439\u0434\u0435\u043D\u043E. \u041D\u0430\u0447\u0438\u043D\u0430\u0439\u0442\u0435 \u043F\u043E\u0434\u044A\u0451\u043C, \u0445\u0443\u0436\u0435 \u0443\u0436\u0435 \u0431\u044B\u043B\u043E.", "m": "\u0421\u0430\u043C\u043E\u0435 \u0442\u044F\u0436\u0451\u043B\u043E\u0435 \u043F\u043E\u0437\u0430\u0434\u0438. \u0412\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0443\u0436\u0435 \u043D\u0430\u0447\u0430\u043B\u043E\u0441\u044C.", "a": "\u0412\u0441\u0442\u0430\u043D\u044C\u0442\u0435. \u0425\u0443\u0434\u0448\u0435\u0435 \u0441\u043B\u0443\u0447\u0438\u043B\u043E\u0441\u044C \u0438 \u043A\u043E\u043D\u0447\u0438\u043B\u043E\u0441\u044C." }, "swords_page": { "l": "\u0417\u0430 \u0432\u0430\u043C\u0438 \u043D\u0430\u0431\u043B\u044E\u0434\u0430\u044E\u0442. \u041F\u043E\u0441\u0442\u0443\u043F\u043A\u0438 \u0441\u043A\u0430\u0436\u0443\u0442 \u0431\u043E\u043B\u044C\u0448\u0435, \u0447\u0435\u043C \u043B\u044E\u0431\u043E\u0435 \u043F\u0440\u0438\u0437\u043D\u0430\u043D\u0438\u0435.", "w": "\u0418\u043D\u0444\u043E\u0440\u043C\u0430\u0446\u0438\u044F \u0440\u0435\u0448\u0430\u0435\u0442. \u041A\u043E\u043F\u0430\u0439\u0442\u0435 \u0433\u043B\u0443\u0431\u0436\u0435, \u0441\u043B\u0443\u0448\u0430\u0439\u0442\u0435 \u0432\u043D\u0438\u043C\u0430\u0442\u0435\u043B\u044C\u043D\u043E.", "m": "\u0418\u0437\u0443\u0447\u0438\u0442\u0435 \u0443\u0441\u043B\u043E\u0432\u0438\u044F \u0434\u043E \u043C\u0435\u043B\u043E\u0447\u0435\u0439, \u043F\u0440\u0435\u0436\u0434\u0435 \u0447\u0435\u043C \u0431\u0440\u0430\u0442\u044C.", "a": "\u0421\u043B\u0443\u0448\u0430\u0439\u0442\u0435 \u0438 \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u0439\u0442\u0435. \u0421\u0435\u0433\u043E\u0434\u043D\u044F \u044D\u0442\u043E \u0432\u0430\u0436\u043D\u0435\u0435 \u043C\u043D\u0435\u043D\u0438\u044F." }, "swords_knight": { "l": "\u0427\u0435\u043B\u043E\u0432\u0435\u043A \u0443\u0436\u0435 \u0440\u0435\u0448\u0438\u043B \u0438 \u043D\u0435\u0441\u0451\u0442\u0441\u044F \u0432\u043F\u0435\u0440\u0451\u0434. \u0414\u043B\u044F \u0447\u0443\u0432\u0441\u0442\u0432\u0430 \u0440\u0430\u043D\u043E, \u043E\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u0442\u044C \u043F\u043E\u0437\u0434\u043D\u043E.", "w": "\u0410\u0442\u0430\u043A\u0430. \u0414\u0435\u0439\u0441\u0442\u0432\u0443\u0439\u0442\u0435, \u043D\u043E \u043D\u0435 \u0440\u0443\u0431\u0438\u0442\u0435 \u0441\u043F\u043B\u0435\u0447\u0430 \u0442\u043E, \u0447\u0442\u043E \u0435\u0449\u0451 \u043F\u0440\u0438\u0433\u043E\u0434\u0438\u0442\u0441\u044F.", "m": "\u0418\u043C\u043F\u0443\u043B\u044C\u0441 \u0441 \u0434\u0435\u043D\u044C\u0433\u0430\u043C\u0438 \u043E\u043F\u0430\u0441\u0435\u043D. \u0427\u0430\u0441 \u043F\u0430\u0443\u0437\u044B \u0434\u043E\u0440\u043E\u0436\u0435 \u043E\u0448\u0438\u0431\u043A\u0438.", "a": "\u0414\u0432\u0438\u0433\u0430\u0439\u0442\u0435\u0441\u044C \u0431\u044B\u0441\u0442\u0440\u043E, \u043D\u043E \u043D\u0435 \u043B\u043E\u043C\u0430\u0439\u0442\u0435." }, "swords_queen": { "l": "\u0421\u043C\u043E\u0442\u0440\u044F\u0442 \u0442\u0440\u0435\u0437\u0432\u043E, \u0431\u0435\u0437 \u0438\u043B\u043B\u044E\u0437\u0438\u0439. \u041B\u044E\u0431\u044F\u0442 \u044F\u0441\u043D\u043E \u0438\u043B\u0438 \u043D\u0435 \u0438\u0433\u0440\u0430\u044E\u0442 \u0432 \u0442\u0443\u043C\u0430\u043D.", "w": "\u0412\u0430\u0448 \u043E\u043F\u044B\u0442 \u0438 \u0447\u0435\u0441\u0442\u043D\u043E\u0441\u0442\u044C \u2014 \u0433\u043B\u0430\u0432\u043D\u044B\u0439 \u0430\u0440\u0433\u0443\u043C\u0435\u043D\u0442. \u0413\u043E\u0432\u043E\u0440\u0438\u0442\u0435 \u043F\u0440\u044F\u043C\u043E.", "m": "\u0420\u0435\u0448\u0430\u0439\u0442\u0435 \u043F\u043E \u0442\u0430\u0431\u043B\u0438\u0446\u0435, \u043D\u0435 \u043F\u043E \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043D\u0438\u044E.", "a": "\u0421\u043A\u0430\u0436\u0438\u0442\u0435 \u043F\u0440\u0430\u0432\u0434\u0443 \u0431\u0435\u0440\u0435\u0436\u043D\u043E. \u0412\u0430\u0441 \u0443\u0441\u043B\u044B\u0448\u0430\u0442." }, "swords_king": { "l": "\u0420\u0435\u0448\u0430\u044E\u0442 \u0433\u043E\u043B\u043E\u0432\u043E\u0439. \u041E\u0431\u0435\u0449\u0430\u043D\u0438\u0435 \u0438 \u0444\u0430\u043A\u0442 \u0434\u043B\u044F \u044D\u0442\u043E\u0433\u043E \u0447\u0435\u043B\u043E\u0432\u0435\u043A\u0430 \u0432\u0435\u0441\u044F\u0442 \u0431\u043E\u043B\u044C\u0448\u0435 \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043D\u0438\u044F.", "w": "\u041D\u0430 \u0440\u0430\u0431\u043E\u0442\u0435 \u0441\u0435\u0439\u0447\u0430\u0441 \u043F\u0440\u0430\u0432\u044F\u0442 \u0444\u0430\u043A\u0442\u044B \u0438 \u043F\u0440\u0430\u0432\u0438\u043B\u0430. \u0421\u043C\u043E\u0442\u0440\u0438\u0442\u0435, \u043A\u0442\u043E \u0441\u0443\u0434\u044C\u044F, \u0438 \u043D\u0435 \u0441\u0443\u0434\u0438\u0442\u0435 \u0447\u0443\u0436\u043E\u0439 \u0441\u0442\u043E\u043B.", "m": "\u0421\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u043F\u043E \u0444\u0430\u043A\u0442\u0430\u043C. \u0415\u0441\u043B\u0438 \u0441\u0430\u043C\u0438 \u043D\u0435 \u0432\u0438\u0434\u0438\u0442\u0435 \u0446\u0438\u0444\u0440, \u0441\u043F\u0440\u043E\u0441\u0438\u0442\u0435 \u0443 \u0442\u043E\u0433\u043E, \u043A\u0442\u043E \u0432\u0438\u0434\u0438\u0442.", "a": "\u0421\u0443\u0434\u0438\u0442\u0435 \u043F\u043E \u0444\u0430\u043A\u0442\u0430\u043C, \u043D\u0435 \u043F\u043E \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043D\u0438\u044E." }, "pentacles_ace": { "l": "\u0417\u0430\u0431\u043E\u0442\u0430 \u043A\u043E\u043D\u043A\u0440\u0435\u0442\u043D\u0430\u044F: \u0441\u0442\u043E\u043B, \u0434\u043E\u043C, \u0434\u0435\u043B\u043E. \u0413\u0440\u043E\u043C\u043A\u0438\u0445 \u043F\u0440\u0438\u0437\u043D\u0430\u043D\u0438\u0439 \u043C\u043E\u0436\u0435\u0442 \u043D\u0435 \u0431\u044B\u0442\u044C. \u0421\u043C\u043E\u0442\u0440\u0438\u0442\u0435, \u0447\u0442\u043E \u043A\u043B\u0430\u0434\u0443\u0442 \u0432 \u0440\u0443\u043A\u0438.", "w": "\u041D\u043E\u0432\u043E\u0435 \u0434\u0435\u043B\u043E \u043C\u043E\u0436\u043D\u043E \u043D\u0430\u0447\u0430\u0442\u044C \u0441\u043F\u043E\u043A\u043E\u0439\u043D\u043E \u0438 \u0432\u0441\u0435\u0440\u044C\u0451\u0437. \u042D\u0442\u043E \u0441\u0435\u043C\u044F, \u043D\u0435 \u0432\u0441\u043F\u044B\u0448\u043A\u0430.", "m": "\u041F\u0435\u0440\u0432\u0430\u044F \u043C\u043E\u043D\u0435\u0442\u0430 \u0443\u0436\u0435 \u0432 \u0440\u0443\u043A\u0430\u0445. \u041D\u0435 \u0442\u0440\u0430\u0442\u044C\u0442\u0435 \u0435\u0451 \u0441\u0440\u0430\u0437\u0443, \u043F\u043E\u0441\u0430\u0434\u0438\u0442\u0435.", "a": "\u041F\u0440\u0438\u043C\u0438\u0442\u0435 \u0442\u043E, \u0447\u0442\u043E \u043F\u0440\u0438\u0448\u043B\u043E, \u0438 \u0434\u0430\u0439\u0442\u0435 \u0435\u043C\u0443 \u0437\u0435\u043C\u043B\u044E." }, "pentacles_2": { "l": "\u0412\u043D\u0438\u043C\u0430\u043D\u0438\u0435 \u0434\u0435\u043B\u0438\u0442\u0441\u044F \u043D\u0430 \u0434\u0432\u0430. \u0412\u044B \u043D\u0435 \u0435\u0434\u0438\u043D\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0435, \u043A\u043E\u043C\u0443 \u0435\u0433\u043E \u0441\u0435\u0439\u0447\u0430\u0441 \u043D\u0435\u0441\u0443\u0442.", "w": "\u0414\u0432\u0430 \u043F\u0440\u043E\u0435\u043A\u0442\u0430 \u0432 \u0440\u0443\u043A\u0430\u0445. \u0427\u0435\u0440\u0435\u0434\u0443\u0439\u0442\u0435, \u0442\u0440\u0435\u0442\u044C\u0435 \u043D\u0435 \u0445\u0432\u0430\u0442\u0430\u0439\u0442\u0435.", "m": "\u0421\u043B\u0435\u0434\u0438\u0442\u0435 \u0437\u0430 \u043F\u0440\u0438\u0445\u043E\u0434\u043E\u043C \u0438 \u0440\u0430\u0441\u0445\u043E\u0434\u043E\u043C \u0441\u0440\u0430\u0437\u0443. \u0420\u0438\u0442\u043C \u0432\u0430\u0436\u043D\u0435\u0435 \u0440\u044B\u0432\u043A\u0430.", "a": "\u041D\u0430\u0439\u0434\u0438\u0442\u0435 \u0440\u0438\u0442\u043C. \u0421\u0435\u0433\u043E\u0434\u043D\u044F \u0441\u0438\u043B\u0430 \u0432 \u0442\u043E\u043C, \u0447\u0442\u043E\u0431\u044B \u043D\u0435 \u0443\u0440\u043E\u043D\u0438\u0442\u044C \u043D\u0438 \u043E\u0434\u043D\u0443 \u043C\u043E\u043D\u0435\u0442\u0443." }, "pentacles_3": { "l": "\u0421\u0431\u043B\u0438\u0436\u0430\u0435\u0442 \u043E\u0431\u0449\u0435\u0435 \u0434\u0435\u043B\u043E \u0441\u0438\u043B\u044C\u043D\u0435\u0435 \u0440\u0430\u0437\u0433\u043E\u0432\u043E\u0440\u043E\u0432 \u043E \u043B\u044E\u0431\u0432\u0438.", "w": "\u041F\u043E\u043A\u0430\u0436\u0438\u0442\u0435 \u0447\u0435\u0440\u043D\u043E\u0432\u0438\u043A \u0442\u0435\u043C, \u043A\u0442\u043E \u043C\u043E\u0436\u0435\u0442 \u043E\u0446\u0435\u043D\u0438\u0442\u044C. \u0412 \u0441\u0442\u043E\u043B \u043F\u0440\u044F\u0442\u0430\u0442\u044C \u0440\u0430\u043D\u043E.", "m": "\u041F\u043B\u0430\u0442\u044F\u0442 \u0437\u0430 \u0432\u0438\u0434\u0438\u043C\u043E\u0435 \u043C\u0430\u0441\u0442\u0435\u0440\u0441\u0442\u0432\u043E. \u0421\u043F\u0440\u044F\u0442\u0430\u043D\u043D\u043E\u0435 \u043D\u0435 \u043A\u043E\u0440\u043C\u0438\u0442.", "a": "\u041F\u043E\u0437\u043E\u0432\u0438\u0442\u0435 \u0442\u0435\u0445, \u0431\u0435\u0437 \u043A\u043E\u0433\u043E \u0434\u0435\u043B\u043E \u043D\u0435 \u0437\u0430\u043A\u0440\u044B\u0442\u044C." }, "pentacles_4": { "l": "\u0421\u0432\u043E\u0451 \u0434\u0435\u0440\u0436\u0430\u0442 \u043A\u0440\u0435\u043F\u043A\u043E. \u0421\u0435\u0440\u0434\u0446\u0435 \u043D\u0430 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0443 \u043D\u0435 \u043E\u0442\u0434\u0430\u044E\u0442.", "w": "\u0417\u0430\u043A\u0440\u0435\u043F\u0438\u0442\u0435 \u043C\u0435\u0441\u0442\u043E. \u0417\u0430 \u043D\u043E\u0432\u044B\u043C \u0433\u043D\u0430\u0442\u044C\u0441\u044F \u0441\u0435\u0439\u0447\u0430\u0441 \u0440\u0430\u043D\u043E.", "m": "\u041A\u043E\u043F\u0438\u0442\u0435. \u041A\u0440\u0443\u043F\u043D\u0430\u044F \u0442\u0440\u0430\u0442\u0430 \u043F\u043E\u0434\u043E\u0436\u0434\u0451\u0442.", "a": "\u0421\u043E\u0436\u043C\u0438\u0442\u0435 \u0432 \u043B\u0430\u0434\u043E\u043D\u0438 \u0442\u043E, \u0447\u0442\u043E \u0443\u0436\u0435 \u0435\u0441\u0442\u044C, \u0438 \u0432\u044B\u0434\u043E\u0445\u043D\u0438\u0442\u0435." }, "pentacles_5": { "l": "\u0421\u0435\u0439\u0447\u0430\u0441 \u0445\u043E\u043B\u043E\u0434\u043D\u043E \u0438 \u0441\u043A\u0443\u0434\u043D\u043E. \u041C\u043E\u0433\u0443\u0442 \u043D\u0435 \u043F\u043E\u0441\u0442\u0443\u0447\u0430\u0442\u044C \u043E\u0442 \u0433\u043E\u0440\u0434\u043E\u0441\u0442\u0438, \u0430 \u043D\u0435 \u043F\u043E\u0442\u043E\u043C\u0443 \u0447\u0442\u043E \u0432\u044B \u043D\u0435 \u043D\u0443\u0436\u043D\u044B.", "w": "\u041D\u0435\u0445\u0432\u0430\u0442\u043A\u0430. \u0421\u043A\u0430\u0436\u0438\u0442\u0435 \u043E\u0431 \u044D\u0442\u043E\u043C, \u043F\u043E\u043A\u0430 \u043D\u0435 \u0441\u0442\u0430\u043B\u043E \u0445\u0443\u0436\u0435.", "m": "\u0422\u0443\u0433\u043E. \u041C\u0430\u043B\u0435\u043D\u044C\u043A\u0430\u044F \u043F\u043E\u043C\u043E\u0449\u044C \u043B\u0443\u0447\u0448\u0435 \u0434\u043E\u043B\u0433\u043E\u0433\u043E \u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044F.", "a": "\u041F\u043E\u0441\u0442\u0443\u0447\u0438\u0442\u0435. \u0414\u0432\u0435\u0440\u044C, \u043A\u043E\u0442\u043E\u0440\u0443\u044E \u043E\u0431\u0445\u043E\u0434\u0438\u0442\u0435, \u043A\u0430\u043A \u0440\u0430\u0437 \u043E\u0442\u043A\u0440\u044B\u0442\u0430." }, "pentacles_6": { "l": "\u0417\u0430\u0431\u043E\u0442\u0430 \u0434\u043E\u043B\u0436\u043D\u0430 \u0445\u043E\u0434\u0438\u0442\u044C \u0442\u0443\u0434\u0430 \u0438 \u043E\u0431\u0440\u0430\u0442\u043D\u043E. \u041B\u0438\u0431\u043E \u0434\u0430\u044E\u0442, \u043B\u0438\u0431\u043E \u0436\u0434\u0443\u0442 \u043E\u0442\u0434\u0430\u0447\u0438.", "w": "\u0421\u043F\u0440\u0430\u0432\u0435\u0434\u043B\u0438\u0432\u0430\u044F \u043F\u043B\u0430\u0442\u0430 \u0438 \u0441\u043F\u0440\u0430\u0432\u0435\u0434\u043B\u0438\u0432\u0430\u044F \u043F\u0440\u043E\u0441\u044C\u0431\u0430. \u041D\u0435 \u0441\u0442\u0435\u0441\u043D\u044F\u0439\u0442\u0435\u0441\u044C \u043D\u0438 \u0442\u043E\u0433\u043E, \u043D\u0438 \u0434\u0440\u0443\u0433\u043E\u0433\u043E.", "m": "\u041F\u043E\u0434\u0435\u043B\u0438\u0442\u0435\u0441\u044C \u0438 \u043D\u0435 \u0441\u0442\u0435\u0441\u043D\u044F\u0439\u0442\u0435\u0441\u044C \u0432\u0437\u044F\u0442\u044C \u0441\u0432\u043E\u0451.", "a": "\u0414\u0430\u0439\u0442\u0435 \u043E\u0434\u043D\u0443 \u043C\u043E\u043D\u0435\u0442\u0443 \u0438 \u0432\u043E\u0437\u044C\u043C\u0438\u0442\u0435 \u043E\u0434\u043D\u0443. \u041C\u0435\u0440\u0430 \u0432\u0430\u0436\u043D\u0435\u0435 \u0449\u0435\u0434\u0440\u043E\u0441\u0442\u0438." }, "pentacles_7": { "l": "\u0427\u0443\u0432\u0441\u0442\u0432\u043E \u0435\u0449\u0451 \u0440\u0430\u0441\u0442\u0451\u0442 \u0432 \u0437\u0435\u043C\u043B\u0435. \u0421\u0440\u044B\u0432\u0430\u0442\u044C \u043F\u043B\u043E\u0434 \u0440\u0430\u043D\u043E. \u042D\u0442\u043E \u0441\u0440\u043E\u043A, \u043D\u0435 \u043E\u0442\u043A\u0430\u0437.", "w": "\u041F\u0430\u0443\u0437\u0430 \u043F\u0435\u0440\u0435\u0434 \u0441\u0431\u043E\u0440\u043E\u043C. \u041D\u0435 \u043F\u0435\u0440\u0435\u0434\u0435\u043B\u044B\u0432\u0430\u0439\u0442\u0435 \u043F\u043E\u0441\u0435\u044F\u043D\u043D\u043E\u0435.", "m": "\u0423\u0440\u043E\u0436\u0430\u0439 \u0435\u0449\u0451 \u043D\u0435 \u0437\u0434\u0435\u0441\u044C. \u041D\u0435 \u0441\u043D\u0438\u043C\u0430\u0439\u0442\u0435 \u0440\u0430\u043D\u044C\u0448\u0435 \u0441\u0440\u043E\u043A\u0430.", "a": "\u041F\u043E\u0434\u043E\u0436\u0434\u0438\u0442\u0435. \u0420\u043E\u0441\u0442 \u0438\u0434\u0451\u0442 \u0431\u0435\u0437 \u0432\u0430\u0448\u0435\u0439 \u0441\u043F\u0435\u0448\u043A\u0438." }, "pentacles_8": { "l": "\u041B\u044E\u0431\u043E\u0432\u044C \u0437\u0434\u0435\u0441\u044C \u2014 \u043F\u043E\u0432\u0442\u043E\u0440 \u043C\u0435\u043B\u043E\u0447\u0435\u0439, \u043D\u0435 \u0440\u0435\u0447\u044C. \u0412\u0435\u0440\u043D\u043E\u0441\u0442\u044C \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u044E\u0442 \u0440\u0443\u043A\u0430\u043C\u0438.", "w": "\u0423\u0447\u0438\u0442\u0435\u0441\u044C \u0440\u0443\u043A\u0430\u043C\u0438. \u041C\u0430\u0441\u0442\u0435\u0440\u0441\u0442\u0432\u043E \u043B\u044E\u0431\u0438\u0442 \u043F\u043E\u0432\u0442\u043E\u0440.", "m": "\u0417\u0430\u0440\u0430\u0431\u043E\u0442\u043E\u043A \u0440\u0430\u0441\u0442\u0451\u0442 \u043E\u0442 \u043D\u0430\u0432\u044B\u043A\u0430, \u043D\u0435 \u043E\u0442 \u0441\u043B\u0443\u0447\u0430\u044F.", "a": "\u0421\u044F\u0434\u044C\u0442\u0435 \u0438 \u0441\u0434\u0435\u043B\u0430\u0439\u0442\u0435 \u0435\u0449\u0451 \u043E\u0434\u043D\u0443. \u0418\u043C\u0435\u043D\u043D\u043E \u044D\u0442\u0443." }, "pentacles_9": { "l": "\u0427\u0435\u043B\u043E\u0432\u0435\u043A \u0443\u0436\u0435 \u0432 \u0441\u0432\u043E\u0451\u043C \u0441\u0430\u0434\u0443. \u0421\u043C\u043E\u0442\u0440\u0438\u0442\u0435, \u0437\u043E\u0432\u0443\u0442 \u043B\u0438 \u0432\u0430\u0441 \u0432\u043D\u0443\u0442\u0440\u044C \u0438\u043B\u0438 \u043E\u0441\u0442\u0430\u0432\u043B\u044F\u044E\u0442 \u0437\u0430 \u043A\u0430\u043B\u0438\u0442\u043A\u043E\u0439.", "w": "\u0412\u044B \u0443\u043C\u0435\u0435\u0442\u0435 \u044D\u0442\u043E \u0441\u0430\u043C\u0438. \u0427\u0443\u0436\u043E\u0439 \u043E\u0446\u0435\u043D\u043A\u0438 \u043C\u043E\u0436\u043D\u043E \u043D\u0435 \u0436\u0434\u0430\u0442\u044C.", "m": "\u0414\u043E\u0441\u0442\u0430\u0442\u043E\u043A \u0442\u0438\u0445\u0438\u0439 \u0438 \u0441\u0432\u043E\u0439. \u041D\u0435 \u0441\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u0439\u0442\u0435 \u0441 \u0447\u0443\u0436\u0438\u043C \u0441\u0430\u0434\u043E\u043C.", "a": "\u0412\u044B\u0439\u0434\u0438\u0442\u0435 \u0432 \u0441\u0432\u043E\u0439 \u0441\u0430\u0434. \u041E\u043D \u0443\u0436\u0435 \u043F\u043B\u043E\u0434\u043E\u043D\u043E\u0441\u0438\u0442." }, "pentacles_10": { "l": "\u041D\u0443\u0436\u0435\u043D \u0434\u043E\u043B\u0433\u0438\u0439 \u043A\u0440\u0443\u0433: \u0441\u0435\u043C\u044C\u044F, \u0434\u043E\u043C, \u0433\u043E\u0434\u044B. \u041E\u0434\u043D\u043E\u0433\u043E \u0432\u0435\u0447\u0435\u0440\u0430 \u044D\u0442\u043E\u043C\u0443 \u0447\u0435\u043B\u043E\u0432\u0435\u043A\u0443 \u043C\u0430\u043B\u043E.", "w": "\u0414\u0435\u043B\u043E \u0434\u0435\u0440\u0436\u0438\u0442 \u043D\u0435 \u043E\u0434\u043D\u043E\u0433\u043E \u0432\u0430\u0441. \u0414\u0443\u043C\u0430\u0439\u0442\u0435 \u043E \u0442\u0435\u0445, \u043A\u0442\u043E \u0441\u0442\u043E\u0438\u0442 \u0440\u044F\u0434\u043E\u043C.", "m": "\u0420\u0435\u0447\u044C \u043E \u043D\u0430\u0441\u043B\u0435\u0434\u0438\u0438 \u0438 \u043E\u0431\u0449\u0435\u043C \u043A\u043E\u0442\u043B\u0435. \u0421\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u043D\u0430 \u0433\u043E\u0434\u044B, \u043D\u0435 \u043D\u0430 \u0432\u0435\u0447\u0435\u0440.", "a": "\u0421\u043E\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u0432\u043E\u0438\u0445. \u0411\u043E\u0433\u0430\u0442\u0441\u0442\u0432\u043E \u0437\u0434\u0435\u0441\u044C \u0432 \u0442\u043E\u043C, \u043A\u0442\u043E \u0440\u044F\u0434\u043E\u043C." }, "pentacles_page": { "l": "\u041D\u0430\u0447\u0430\u043B\u043E \u0440\u043E\u0431\u043A\u043E\u0435 \u0438 \u043C\u0430\u043B\u0435\u043D\u044C\u043A\u043E\u0435. \u041D\u0435 \u0442\u043E\u0440\u043E\u043F\u0438\u0442\u0435 \u0435\u0433\u043E \u0432 \u0431\u043E\u043B\u044C\u0448\u043E\u0435.", "w": "\u0423\u0447\u0451\u0431\u0430, \u0441\u0442\u0430\u0436\u0438\u0440\u043E\u0432\u043A\u0430, \u043F\u0435\u0440\u0432\u043E\u0435 \u043F\u043E\u0440\u0443\u0447\u0435\u043D\u0438\u0435. \u0420\u0430\u0441\u0441\u043C\u043E\u0442\u0440\u0438\u0442\u0435, \u043D\u0435 \u043F\u0440\u0435\u0437\u0438\u0440\u0430\u0439\u0442\u0435.", "m": "\u041F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0441\u043A\u0440\u043E\u043C\u043D\u043E\u0435. \u0418\u0437\u0443\u0447\u0438\u0442\u0435, \u043F\u0440\u0435\u0436\u0434\u0435 \u0447\u0435\u043C \u0431\u0440\u0430\u0442\u044C.", "a": "\u0412\u043E\u0437\u044C\u043C\u0438\u0442\u0435 \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E\u0441\u0442\u044C \u0432 \u0440\u0443\u043A\u0438 \u0438 \u043F\u043E\u0441\u043C\u043E\u0442\u0440\u0438\u0442\u0435, \u0447\u0442\u043E \u043D\u0430 \u043D\u0435\u0439 \u043D\u0430\u043F\u0438\u0441\u0430\u043D\u043E." }, "pentacles_knight": { "l": "\u0427\u0435\u043B\u043E\u0432\u0435\u043A \u0438\u0434\u0451\u0442 \u043C\u0435\u0434\u043B\u0435\u043D\u043D\u043E \u0438 \u043D\u0430\u0434\u0451\u0436\u043D\u043E. \u0411\u0443\u0434\u0435\u0442 \u043D\u0430 \u043C\u0435\u0441\u0442\u0435, \u0431\u0435\u0437 \u043F\u044B\u043B\u0430.", "w": "\u041C\u0435\u0434\u043B\u0435\u043D\u043D\u044B\u0439 \u0445\u043E\u0434, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u0434\u043E\u0435\u0437\u0436\u0430\u0435\u0442. \u041D\u0435 \u0443\u0441\u043A\u043E\u0440\u044F\u0439\u0442\u0435\u0441\u044C.", "m": "\u041A\u043E\u043F\u0438\u0442\u0435 \u0448\u0430\u0433\u043E\u043C, \u043D\u0435 \u0440\u044B\u0432\u043A\u043E\u043C.", "a": "\u041D\u0435 \u0441\u0445\u043E\u0434\u0438\u0442\u0435 \u0441 \u0434\u043E\u0440\u043E\u0433\u0438. \u0421\u0435\u0433\u043E\u0434\u043D\u044F \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u0442\u043E\u0442, \u043A\u0442\u043E \u043D\u0435 \u0441\u043F\u0435\u0448\u0438\u0442." }, "pentacles_queen": { "l": "\u0417\u0430\u0431\u043E\u0442\u0430 \u0440\u0443\u043A\u0430\u043C\u0438: \u043D\u0430\u043A\u043E\u0440\u043C\u0438\u0442\u044C, \u0443\u0441\u0442\u0440\u043E\u0438\u0442\u044C. \u0422\u0430\u043A \u044D\u0442\u043E\u0442 \u0447\u0435\u043B\u043E\u0432\u0435\u043A \u043B\u044E\u0431\u0438\u0442, \u0430 \u043D\u0435 \u0440\u0435\u0447\u0430\u043C\u0438.", "w": "\u0412\u044B \u0443\u043C\u0435\u0435\u0442\u0435 \u0440\u0430\u0441\u0442\u0438\u0442\u044C \u043B\u044E\u0434\u0435\u0439 \u0438 \u043F\u0440\u043E\u0435\u043A\u0442\u044B. \u0422\u0435\u043F\u043B\u043E \u0437\u0434\u0435\u0441\u044C \u0432 \u0434\u0435\u043B\u0435.", "m": "\u0414\u043E\u0441\u0442\u0430\u0442\u043E\u043A \u043E\u0442 \u0443\u0445\u043E\u0436\u0435\u043D\u043D\u043E\u0433\u043E, \u043D\u0435 \u043E\u0442 \u0441\u043B\u0443\u0447\u0430\u0439\u043D\u043E\u0433\u043E.", "a": "\u0421\u043E\u0433\u0440\u0435\u0439\u0442\u0435 \u0442\u043E, \u0447\u0442\u043E \u043A\u043E\u0440\u043C\u0438\u0442 \u044D\u0442\u043E\u0442 \u0432\u043E\u043F\u0440\u043E\u0441. \u041D\u0435 \u0432\u0441\u0435\u0445 \u043F\u043E\u0434\u0440\u044F\u0434." }, "pentacles_king": { "l": "\u0414\u0435\u0440\u0436\u0430\u0442 \u0441\u043B\u043E\u0432\u043E, \u043A\u0430\u043A \u0445\u043E\u0437\u044F\u0438\u043D. \u041E\u0431\u0435\u0449\u0430\u044E\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u0442\u043E, \u0447\u0442\u043E \u0443\u0434\u0435\u0440\u0436\u0430\u0442.", "w": "\u041E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u0441\u0442\u044C \u0438 \u044F\u0441\u043D\u044B\u0439 \u043F\u043E\u0440\u044F\u0434\u043E\u043A. \u0420\u0435\u0448\u0430\u0439\u0442\u0435 \u0441\u043F\u043E\u043A\u043E\u0439\u043D\u043E \u0438 \u043D\u0430\u0434\u043E\u043B\u0433\u043E.", "m": "\u0421\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u043A\u0430\u043A \u0445\u043E\u0437\u044F\u0438\u043D, \u043D\u0435 \u043A\u0430\u043A \u0433\u043E\u0441\u0442\u044C.", "a": "\u0421\u044F\u0434\u044C\u0442\u0435 \u043D\u0430 \u0441\u0432\u043E\u0451 \u043C\u0435\u0441\u0442\u043E \u0438 \u0440\u0435\u0448\u0438\u0442\u0435. \u0417\u0435\u043C\u043B\u044F \u0443\u0436\u0435 \u0432\u0430\u0448\u0430." } };
  var ARCANA = [["\u041C\u0430\u0433", "\u0412\u0430\u0448 \u0440\u0435\u0441\u0443\u0440\u0441 \u2014 \u0432\u043E\u043B\u044F \u0438 \u0443\u043C\u0435\u043D\u0438\u0435 \u043D\u0430\u0447\u0438\u043D\u0430\u0442\u044C: \u0437\u0430\u0434\u0443\u043C\u0430\u043D\u043D\u043E\u0435 \u043F\u043E\u0434\u0434\u0430\u0451\u0442\u0441\u044F, \u043A\u043E\u0433\u0434\u0430 \u0432\u044B \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442\u0435."], ["\u0412\u0435\u0440\u0445\u043E\u0432\u043D\u0430\u044F \u0416\u0440\u0438\u0446\u0430", "\u0412\u0430\u0448\u0430 \u0441\u0438\u043B\u0430 \u2014 \u0438\u043D\u0442\u0443\u0438\u0446\u0438\u044F: \u043E\u0442\u0432\u0435\u0442\u044B \u043F\u0440\u0438\u0445\u043E\u0434\u044F\u0442 \u0432 \u0442\u0438\u0448\u0438\u043D\u0435, \u0434\u043E\u0432\u0435\u0440\u044F\u0439\u0442\u0435 \u0432\u043D\u0443\u0442\u0440\u0435\u043D\u043D\u0435\u043C\u0443 \u0433\u043E\u043B\u043E\u0441\u0443."], ["\u0418\u043C\u043F\u0435\u0440\u0430\u0442\u0440\u0438\u0446\u0430", "\u0412\u0430\u0448 \u0440\u0435\u0441\u0443\u0440\u0441 \u2014 \u0441\u043E\u0437\u0438\u0434\u0430\u043D\u0438\u0435: \u0432\u044B \u0440\u0430\u0441\u0442\u0438\u0442\u0435 \u0438\u0434\u0435\u0438, \u043B\u044E\u0434\u0435\u0439 \u0438 \u043F\u0440\u043E\u0435\u043A\u0442\u044B, \u043A\u0430\u043A \u0441\u0430\u0434."], ["\u0418\u043C\u043F\u0435\u0440\u0430\u0442\u043E\u0440", "\u0412\u0430\u0448\u0430 \u043E\u043F\u043E\u0440\u0430 \u2014 \u0441\u0442\u0440\u0443\u043A\u0442\u0443\u0440\u0430: \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u0438 \u0433\u0440\u0430\u043D\u0438\u0446\u044B \u0434\u0430\u044E\u0442 \u0432\u0430\u043C \u0441\u0438\u043B\u0443 \u0434\u0432\u0438\u0433\u0430\u0442\u044C\u0441\u044F \u0432\u043F\u0435\u0440\u0451\u0434."], ["\u0418\u0435\u0440\u043E\u0444\u0430\u043D\u0442", "\u0412\u0430\u0448\u0430 \u0441\u0438\u043B\u0430 \u2014 \u0441\u043C\u044B\u0441\u043B \u0438 \u0442\u0440\u0430\u0434\u0438\u0446\u0438\u044F: \u0432\u044B \u0443\u0447\u0438\u0442\u0435\u0441\u044C \u0438 \u0443\u0447\u0438\u0442\u0435, \u043E\u043F\u0438\u0440\u0430\u044F\u0441\u044C \u043D\u0430 \u043F\u0440\u043E\u0432\u0435\u0440\u0435\u043D\u043D\u043E\u0435."], ["\u0412\u043B\u044E\u0431\u043B\u0451\u043D\u043D\u044B\u0435", "\u0412\u0430\u0448 \u0440\u0435\u0441\u0443\u0440\u0441 \u2014 \u0432\u044B\u0431\u043E\u0440 \u0441\u0435\u0440\u0434\u0446\u0435\u043C: \u0440\u0435\u0448\u0435\u043D\u0438\u044F, \u0441\u0434\u0435\u043B\u0430\u043D\u043D\u044B\u0435 \u0438\u0437 \u043B\u044E\u0431\u0432\u0438, \u0432\u0441\u0435\u0433\u0434\u0430 \u0432\u0435\u0440\u043D\u044B."], ["\u041A\u043E\u043B\u0435\u0441\u043D\u0438\u0446\u0430", "\u0412\u0430\u0448\u0430 \u0441\u0438\u043B\u0430 \u2014 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435: \u0446\u0435\u043B\u044C \u0438 \u0443\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u043C\u044B\u0439 \u043D\u0430\u043F\u043E\u0440 \u0432\u0435\u0434\u0443\u0442 \u0432\u0430\u0441 \u0434\u0430\u043B\u044C\u0448\u0435 \u0434\u0440\u0443\u0433\u0438\u0445."], ["\u0421\u0438\u043B\u0430", "\u0412\u0430\u0448 \u0440\u0435\u0441\u0443\u0440\u0441 \u2014 \u043C\u044F\u0433\u043A\u0430\u044F \u0441\u0442\u043E\u0439\u043A\u043E\u0441\u0442\u044C: \u0432\u044B \u0443\u043A\u0440\u043E\u0449\u0430\u0435\u0442\u0435 \u043E\u0431\u0441\u0442\u043E\u044F\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u0430 \u0442\u0435\u0440\u043F\u0435\u043D\u0438\u0435\u043C, \u0430 \u043D\u0435 \u0434\u0430\u0432\u043B\u0435\u043D\u0438\u0435\u043C."], ["\u041E\u0442\u0448\u0435\u043B\u044C\u043D\u0438\u043A", "\u0412\u0430\u0448\u0430 \u0441\u0438\u043B\u0430 \u2014 \u0433\u043B\u0443\u0431\u0438\u043D\u0430: \u0432 \u043E\u0434\u0438\u043D\u043E\u0447\u0435\u0441\u0442\u0432\u0435 \u0432\u044B \u043D\u0430\u0445\u043E\u0434\u0438\u0442\u0435 \u043E\u0442\u0432\u0435\u0442\u044B, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0438\u0449\u0443\u0442 \u0434\u0440\u0443\u0433\u0438\u0435."], ["\u041A\u043E\u043B\u0435\u0441\u043E \u0424\u043E\u0440\u0442\u0443\u043D\u044B", "\u0412\u0430\u0448 \u0440\u0435\u0441\u0443\u0440\u0441 \u2014 \u0447\u0443\u0442\u044C\u0451 \u043D\u0430 \u043F\u0435\u0440\u0435\u043C\u0435\u043D\u044B: \u043F\u043E\u0432\u043E\u0440\u043E\u0442\u044B \u0441\u0443\u0434\u044C\u0431\u044B \u0440\u0430\u0431\u043E\u0442\u0430\u044E\u0442 \u043D\u0430 \u0432\u0430\u0441."], ["\u0421\u043F\u0440\u0430\u0432\u0435\u0434\u043B\u0438\u0432\u043E\u0441\u0442\u044C", "\u0412\u0430\u0448\u0430 \u043E\u043F\u043E\u0440\u0430 \u2014 \u043F\u0440\u0430\u0432\u0434\u0430: \u044F\u0441\u043D\u043E\u0441\u0442\u044C \u0438 \u0447\u0435\u0441\u0442\u043D\u043E\u0441\u0442\u044C \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u044E\u0442 \u0432\u0430\u043C \u0440\u0430\u0432\u043D\u043E\u0432\u0435\u0441\u0438\u0435."], ["\u041F\u043E\u0432\u0435\u0448\u0435\u043D\u043D\u044B\u0439", "\u0412\u0430\u0448\u0430 \u0441\u0438\u043B\u0430 \u2014 \u0434\u0440\u0443\u0433\u043E\u0439 \u0443\u0433\u043E\u043B: \u043F\u0430\u0443\u0437\u0430 \u0438 \u0441\u043C\u0435\u043D\u0430 \u0432\u0437\u0433\u043B\u044F\u0434\u0430 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u044E\u0442 \u0442\u043E, \u0447\u0435\u0433\u043E \u043D\u0435 \u0432\u0438\u0434\u043D\u043E \u0432 \u0431\u0435\u0433\u0435."], ["\u0421\u043C\u0435\u0440\u0442\u044C", "\u0412\u0430\u0448 \u0440\u0435\u0441\u0443\u0440\u0441 \u2014 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435: \u0432\u044B \u0443\u043C\u0435\u0435\u0442\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0442\u044C \u0433\u043B\u0430\u0432\u044B \u0438 \u043D\u0430\u0447\u0438\u043D\u0430\u0442\u044C \u043D\u043E\u0432\u044B\u0435 \u0431\u0435\u0437 \u0441\u0442\u0440\u0430\u0445\u0430."], ["\u0423\u043C\u0435\u0440\u0435\u043D\u043D\u043E\u0441\u0442\u044C", "\u0412\u0430\u0448\u0430 \u0441\u0438\u043B\u0430 \u2014 \u0431\u0430\u043B\u0430\u043D\u0441: \u0437\u043E\u043B\u043E\u0442\u0430\u044F \u0441\u0435\u0440\u0435\u0434\u0438\u043D\u0430 \u0438 \u0441\u043C\u0435\u0448\u0435\u043D\u0438\u0435 \u043F\u0440\u043E\u0442\u0438\u0432\u043E\u043F\u043E\u043B\u043E\u0436\u043D\u043E\u0441\u0442\u0435\u0439 \u2014 \u0432\u0430\u0448\u0430 \u0430\u043B\u0445\u0438\u043C\u0438\u044F."], ["\u0414\u044C\u044F\u0432\u043E\u043B", "\u0412\u0430\u0448 \u0440\u0435\u0441\u0443\u0440\u0441 \u2014 \u044D\u043D\u0435\u0440\u0433\u0438\u044F \u0436\u0435\u043B\u0430\u043D\u0438\u0439: \u043F\u0440\u0438\u0437\u043D\u0430\u0432 \u0441\u0432\u043E\u0438 \u0442\u0435\u043D\u0438, \u0432\u044B \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442\u0435 \u043D\u0430\u0434 \u043D\u0438\u043C\u0438 \u0432\u043B\u0430\u0441\u0442\u044C."], ["\u0411\u0430\u0448\u043D\u044F", "\u0412\u0430\u0448\u0430 \u0441\u0438\u043B\u0430 \u2014 \u043F\u0435\u0440\u0435\u0441\u0431\u043E\u0440\u043A\u0430: \u043F\u043E\u0441\u043B\u0435 \u043B\u044E\u0431\u044B\u0445 \u0440\u0430\u0437\u0440\u0443\u0448\u0435\u043D\u0438\u0439 \u0432\u044B \u0441\u0442\u0440\u043E\u0438\u0442\u0435 \u0437\u0430\u043D\u043E\u0432\u043E \u0438 \u043A\u0440\u0435\u043F\u0447\u0435."], ["\u0417\u0432\u0435\u0437\u0434\u0430", "\u0412\u0430\u0448 \u0440\u0435\u0441\u0443\u0440\u0441 \u2014 \u043D\u0430\u0434\u0435\u0436\u0434\u0430: \u0432\u044B \u0441\u0432\u0435\u0442\u0438\u0442\u0435 \u0441\u0435\u0431\u0435 \u0438 \u0434\u0440\u0443\u0433\u0438\u043C \u0434\u0430\u0436\u0435 \u0432 \u0441\u0430\u043C\u0443\u044E \u0442\u0451\u043C\u043D\u0443\u044E \u043D\u043E\u0447\u044C."], ["\u041B\u0443\u043D\u0430", "\u0412\u0430\u0448\u0430 \u0441\u0438\u043B\u0430 \u2014 \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u044C: \u0432\u044B \u0441\u043B\u044B\u0448\u0438\u0442\u0435 \u043F\u043E\u0434\u0432\u043E\u0434\u043D\u044B\u0435 \u0442\u0435\u0447\u0435\u043D\u0438\u044F, \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u0435 \u043B\u043E\u0433\u0438\u043A\u0435."], ["\u0421\u043E\u043B\u043D\u0446\u0435", "\u0412\u0430\u0448 \u0440\u0435\u0441\u0443\u0440\u0441 \u2014 \u0440\u0430\u0434\u043E\u0441\u0442\u044C: \u0442\u0435\u043F\u043B\u043E \u0438 \u0436\u0438\u0437\u043D\u0435\u043B\u044E\u0431\u0438\u0435 \u043F\u0440\u0438\u0442\u044F\u0433\u0438\u0432\u0430\u044E\u0442 \u043A \u0432\u0430\u043C \u0443\u0434\u0430\u0447\u0443."], ["\u0421\u0443\u0434", "\u0412\u0430\u0448\u0430 \u0441\u0438\u043B\u0430 \u2014 \u043F\u0440\u043E\u0431\u0443\u0436\u0434\u0435\u043D\u0438\u0435: \u0432\u044B \u0443\u043C\u0435\u0435\u0442\u0435 \u0432\u043E\u0437\u0440\u043E\u0436\u0434\u0430\u0442\u044C\u0441\u044F \u0438 \u043E\u0442\u0432\u0435\u0447\u0430\u0442\u044C \u043D\u0430 \u0437\u043E\u0432 \u043D\u043E\u0432\u043E\u0433\u043E \u044D\u0442\u0430\u043F\u0430."], ["\u041C\u0438\u0440", "\u0412\u0430\u0448 \u0440\u0435\u0441\u0443\u0440\u0441 \u2014 \u0446\u0435\u043B\u043E\u0441\u0442\u043D\u043E\u0441\u0442\u044C: \u0432\u044B \u0441\u043E\u0431\u0438\u0440\u0430\u0435\u0442\u0435 \u0440\u0430\u0437\u0440\u043E\u0437\u043D\u0435\u043D\u043D\u043E\u0435 \u0432 \u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043D\u043D\u0443\u044E \u043A\u0430\u0440\u0442\u0438\u043D\u0443."], ["\u0414\u0443\u0440\u0430\u043A", "\u0412\u0430\u0448\u0430 \u0441\u0438\u043B\u0430 \u2014 \u0441\u0432\u043E\u0431\u043E\u0434\u0430: \u0447\u0438\u0441\u0442\u044B\u0439 \u043B\u0438\u0441\u0442 \u0438 \u0441\u043C\u0435\u043B\u043E\u0441\u0442\u044C \u0448\u0430\u0433\u0430 \u0431\u0435\u0437 \u0433\u0430\u0440\u0430\u043D\u0442\u0438\u0439 \u0432\u0435\u0434\u0443\u0442 \u0432\u0430\u0441 \u043A \u0447\u0443\u0434\u0435\u0441\u0430\u043C."]];

