  function hexSvg(card, changing = -1) {
    const bars = [...card.lines || []].reverse();
    const gap = 11;
    const y0 = 14;
    const parts = bars.map((yang, i) => {
      const y = y0 + i * gap;
      const glow = 5 - i === changing ? ` class="is-change"` : "";
      if (yang) return `<rect${glow} x="14" y="${y}" width="52" height="7" rx="1.2"/>`;
      return `<rect${glow} x="14" y="${y}" width="20" height="7" rx="1.2"/><rect${glow} x="46" y="${y}" width="20" height="7" rx="1.2"/>`;
    }).join("");
    const n = card?.n ? `<text class="hex-n" x="40" y="90" text-anchor="middle">${card.n}</text>` : "";
    return `<svg class="hex-face" viewBox="0 0 80 96" aria-hidden="true"><rect class="hex-bg" x="3" y="3" width="74" height="90" rx="5"/><rect class="hex-in" x="7" y="7" width="66" height="82" rx="3"/>${parts}${n}</svg>`;
  }

