  function dignity(a, b) {
    if (a === b) return "same";
    const pair = [a, b].sort().join("+");
    if (pair === "\u0432\u043E\u0437\u0434\u0443\u0445+\u043E\u0433\u043E\u043D\u044C" || pair === "\u0432\u043E\u0434\u0430+\u0437\u0435\u043C\u043B\u044F") return "friendly";
    if (pair === "\u0432\u043E\u0434\u0430+\u043E\u0433\u043E\u043D\u044C" || pair === "\u0432\u043E\u0437\u0434\u0443\u0445+\u0437\u0435\u043C\u043B\u044F") return "contrary";
    return "neutral";
  }
