      <span><b>${escapeHtml(pack.title)}</b><span>\u0421\u0435\u0433\u043E\u0434\u043D\u044F, \u0434\u043E \u043F\u043E\u043B\u0443\u043D\u043E\u0447\u0438</span></span>
