      const label = last ? knownProfile() && consented() ? "\u0412 \u0437\u0430\u043B" : "\u041D\u0430\u0437\u0432\u0430\u0442\u044C \u0441\u0435\u0431\u044F" : "\u0414\u0430\u043B\u044C\u0448\u0435";
      const body = beat.items ? `<ul class="beat beat-list">${beat.items.map((line) => `<li>${glueShortWords(line)}</li>`).join("")}</ul>` : `<p class="beat">${glueShortWords(beat.text || "")}</p>`;
